// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":88,"question":"لقد درجت وشاعت بعضُ العادات عند القبائل بإحضار مَن يُسَمَّون: شُعراء المحاورة، مثل: أن يأتوا بشاعرين في حفلات العُرس ونحوها، كل واحدٍ منهما من قبيلةٍ، مقابل إعطائهما مبلغًا من المال، ويقوم الشاعران بإحياء الليل كما يقولون، حيث يكون هناك صفَّان مُتقابلان من الرجال، وكل شاعرٍ له صفٌّ، يُرددون ترديدًا جماعيًّا ما يقوله الشَّاعران، بأصواتٍ عاليةٍ، مع التَّصفيق والرقص والتَّمايل، ويفتخر كل شاعرٍ بحسبه ونسبه، ويطعن بالمُقابل في الشاعر الآخر، فما الحكم في هذا كله؟","title":"حكم الشعر بالأعراس مع الرقص والتصفيق","answer":"الجواب: أمَّا الغناء في العُرس من النِّساء بالدُّفوف فهذا من إعلان النكاح، فمشروعٌ ضرب الدف في النكاح للنساء خاصةً، وليس فيه اختلاطٌ، ويكون بالأغاني العادية التي ليس فيها منكر، فهذا مشروعٌ للنساء، وهو من إعلان النكاح، وكان يُفْعَل في عهد النبي ﷺ ويحضره أزواجُه وغيرُهم.\nأما الرجال فلا بأس أن يتعاطوا الشعر العربي، ويجتمعوا عليه ويسمعونه، وهو الذي ليس فيه محذور، وليس فيه غيبة، ولا سبٌّ، ولا شتمٌ، ولا يُسبب الشَّحناء والعداوة، وبدون طبلٍ، وبدون أي منكرٍ آخر من: عيب الناس، أو عيب قبيلة فلان مما يُسبب الشَّحناء، فهذا لا يجوز. أما إذا حضَّروا شعرًا طيبًا: كشعر حسان، والأشعار الطيبة، والقصائد الطيبة التي فيها الخير والدَّعوة إليه، أو قام شاعرٌ يدعوهم إلى الخير: إلى الجود والكرم والأعمال الطيبة، وقام شاعرٌ آخر كذلك يدعو إلى الخير ومكارم الأخلاق ومحاسن الأعمال؛ فلا بأس، وكما قال ﷺ: إنَّ من الشعر لحكمةً، وقال لحسان: اهجُ الكفار، فوالذي نفسي بيده، إنه لأشدّ عليهم من وقع النَّبْل، وقال: اللهم أيِّده بروح القدس، فكان حسانُ يهجوهم، وكانت أشعاره عظيمةً طيبةً، وهكذا عبدالله بن رواحة، وكعب بن مالك، وهكذا مَن بعدهم من الشُّعراء الطيبين.\nومن الشعر: \"نونية ابن القيم\" التي هي من أعظم الشعر وأنفعه، فهي قصيدة طيبة عظيمة نافعة، و\"نونية القحطاني\"، وهي قصيدة طيبة نافعة في العقيدة، وهكذا الأشعار الطيبة التي فيها الدَّعوة إلى الخير وإلى مكارم الأخلاق ومحاسن الأعمال، فهذا طيبٌ في العرس وغير العرس.\nأما أن يقوم شاعران أو أكثر يتناحرون، ويذمّ بعضُهم بعضًا، ويسبُّ بعضُهم بعضًا، أو يسبُّ هذا قبيلةَ هذا، وقبيلةَ هذا؛ فهذا منكر، لكن إذا كان الشعرُ فيما ينفع الناس؛ كالدَّعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وبرّ الوالدين، وصلة الرحم، وطاعة الله ورسوله، وطاعة ولاة الأمور بالمعروف، والحذر من معاصي الله؛ فهذا كله طيبٌ، وله أثرٌ في النفوس.\nولا بأس أن تُعطى المغنية في العُرس أجرةً على عملها، أو الشاعر الذي عنده أشعار طيبة، فيُدْعَى ليقول الشعر الطيب الذي ينفع الناس، ويُعْطَى جائزةً، لا بأس بذلك.\nأما الذي يدعو إلى غيبة فلان، وذمِّ فلان، ومدح فلان؛ لإثارة الشَّحناء والعداوة والبغضاء بين الناس، فهذا منكرٌ لا يجوز -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3091/حكم-الشعر-بالاعراس-مع-الرقص-والتصفيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0065.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":131,"question":"هذه مجموعة أسئلة.. تسأل عن العَرْضَة؟","title":"ما حكم \"العَرْضَة\" ونحوها؟","answer":"الجواب: العرضات إذا كانت لا تمنع من الصلاة ولا تشغل عنها، وليس فيها اختلاط الرجال بالنساء، وفيها اختلاط بالرجال خاصةً، وليس فيها ما يُنْكَر، بالأشعار العربية، أشعار تدعو إلى الجود والكرم والحماس والشجاعة ونحو ذلك، وليس فيها منكر: لا موسيقى، ولا طبول؛ فلا بأس. أما إذا كانت فيها موسيقى وآلات ملاهٍ من طبول وموسيقى، وكانت تشغل عن الصلاة، أو فيها محذورات أخرى، منكرات أخرى: من كشف عورات؛ لا تحضر، لا يجوز حضورها، إلا إذا كانت سليمة: أشعار سليمة، ومجالس سليمة، ولا تشغل عن الصلاة، وليس فيها من آلات الملاهي شيء، لا بأس.","link":"https://binbaz.org.sa/fatwas/3658/ما-حكم-العرضة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0120.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":360,"question":"هل الشعر حرام؟ مع أن حُجّة بعض الناس أن الرسول ﷺ كان له شاعرٌ، وهو حسَّان بن ثابت.","title":"ما الحكم الشرعي في الشعر والشعراء؟","answer":"الجواب: هذا فيه تفصيل أيضًا، والشعر مثلما قال الشافعي رحمه الله: \"حسنه حسن، وقبيحه قبيح\"، فالشعر الذي ينصر الحقَّ ويُؤيد الحقَّ، ويهدم الباطل وأهل الباطل؛ هذا مطلوبٌ، هذا مشروعٌ، وهو الذي كان يقوم به حسان بن ثابت ، وعبدالله بن رواحة، وسعد بن مالك، وغيرهم من الشعراء الذين كانوا في عهده ﷺ وبعده.\nأما إذا كان الشعر في ذمِّ الحق، ومدح الخنا والفساد، والدعوة إلى الزنا والفجور؛ فهذا منكرٌ محض لا يجوز.\nفالشعر يختلف بحسب مقاصده ومراد صاحبه: فإن أراد الحقَّ والخير ومُقتضى شعره يدل على ذلك؛ فلا بأس في ذلك، ومن الدعوة إلى الخير، والدعوة إلى الحق، وإن كان شعره يدعو إلى الباطل والفساد؛ صار مذمومًا يجب منعه منه.","link":"https://binbaz.org.sa/fatwas/4554/ما-الحكم-الشرعي-في-الشعر-والشعراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0413.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":525,"question":"بعض الزواجات -أحسن الله إليك- الواحد وهو يوصل أهله للزواج يسمع صوت الموسيقى والأغاني، يعني أشياء محرمة، هل يأثم إذا ترك أهله يذهبون لهذا الزواج؟","title":"حكم الذهاب لحفلات زواج بها أغانٍ وموسيقى","answer":"الجواب: إذا كان عندهم موسيقى لا تروح لهم، موسيقى أو غيرها من الملاهي لا، أما إذا كان دف فلا بأس للنساء خاصة، أما موسيقى أو طبول أو غير ذلك من المحرمات؛ يُمنع هذا.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6356/حكم-الذهاب-لحفلات-زواج-بها-اغان-وموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/maram091 - 04 - .mp3","categories":["الزفاف ووليمة العرس"]},{"id":760,"question":"الأناشيد الإسلامية هل تدخل في الغناء أم لا؟","title":"ما حكم الأناشيد الإسلامية؟","answer":"الجواب: إذا كانت سليمةً ليس فيها شيءٌ من جنس الشعر: حَسَنُها حسن، وقبيحُها قبيح، فالأناشيد الإسلامية التي تُلقى بأصوات العرب، لا بأصوات النساء، ولا بأصواتٍ تُثير شرًّا، بل بأصواتٍ عربيةٍ إسلاميةٍ، وليس فيها محذورٌ؛ من جنس بقية الشعر: إنَّ من الشعر لحكمة، فالأشعار السليمة بمكارم الأخلاق ومحاسن الأعمال لا بأس بها، وقد أنشد حسان بن ثابتٍ  بين يدي النبي ﷺ هجوه للمشركين، فأقرَّه النبيُّ ﷺ وأمره أن يهجوهم وقال: إنَّ روح القدس معك، وقال: إنه لأشد عليهم من وقع النَّبْل، وهكذا سمع شعر كعب بن مالك، وشعر عبدالله بن رواحة.","link":"https://binbaz.org.sa/fatwas/20684/ما-حكم-الاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0585حكم النشيد الإسلامي؟ ابن باز رحمه الله فتاوى المحاضرات.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":911,"question":"ما حكم حضور حفلات الزفاف التي يوجد فيها الغناء، سواء من الرجال أو من النِّساء؟","title":"حكم حضور حفلات الزفاف التي بها غناء","answer":"الجواب: حفلات الزواج فيها تفصيلٌ: إذا كانت الحفلة مصونةً شرعيةً فلا بأس، يحضرها الرجال والنساء، النساء مع النساء، والرجال مع الرجال. وإذا كانت فيها ما حرَّم الله وجب الامتناعُ، فإذا كان فيها اختلاطُ الرجال بالنساء؛ لم يجز للمرأة أن تحضر معهم، ووجب على أهل الزواج إنكار ذلك، ووجب على الحِسبة إنكار ذلك، حتى لا يحصل هذا الاختلاط.\nكذلك إذا كانت فيها الملاهي: من العود والكمان والطبول؛ وجب المنع. أما الدُّفّ العادي بين النساء فلا بأس، الدُّف الذي له وجهٌ واحدٌ -وهو الطار- تضرب به النساء خاصةً بينهنَّ في ليلة العُرْس؛ لا بأس، هذا يفعل في عهد النبي ﷺ وعهد أصحابه لإعلان النكاح وإظهاره، أما أن يستعمل غير ذلك من الطبول والعود وأشباه ذلك من آلات الملاهي، أو اختلاط النساء بالرجال؛ هذا شيء يضرُّ الناس، وهو منكرٌ، وربما سبب إضاعة الصلاة -صلاة الفجر- بسبب السهر، فهذا لا يجوز.\nفالمقصود أنَّ على أهل العُرْس أن يكون اجتماعُهم وحفلُهم متقيدًا بالشريعة، في بعض الليل؛ حتى يناموا، وحتى لا يُضيِّعوا الفجر.","link":"https://binbaz.org.sa/fatwas/20948/حكم-حضور-حفلات-الزفاف-التي-بها-غناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0744ما حكم حضور حفلات الزفاف التي يوجد فيها الغناء سواء من الرجال أو من النساء ؟ ابن باز.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":941,"question":"ما حكم الأناشيد؟ لأنَّ كثيرًا من الشباب يستمعون إليها ويتركون القرآن، أو يستمعون لها أكثر مما يستمعون إلى القرآن، وإذا كانت تجوز بشروطٍ فما شروطها؟","title":"ما حكم الأناشيد؟ وما شروطها؟","answer":"الجواب: الأناشيد من جنس الشعر: حسنه حسن، وقبيحه قبيح، إذا كانت أناشيد سليمة، معانيها طيبة؛ لا بأس بها، وإن كانت أناشيد رديئة، ومعانيها رديئة؛ مُنِعَتْ، فهي من جنس الشعر، فإذا كانت الأناشيد في مدح الخمور، أو الدَّعوة إلى الفواحش، أو ما أشبه ذلك؛ فهذه تُمنع، أما إذا كانت أناشيد في الحثِّ على العلم، وطلب العلم، وبرِّ الوالدين، وصلة الرحم، والمحافظة على الصلاة، وأشباه ذلك؛ فهي مقبولة.","link":"https://binbaz.org.sa/fatwas/20972/ما-حكم-الاناشيد-وما-شروطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0768ما حكم الأناشيد؟ ابن باز فتاوى المحاضرات.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":972,"question":"إنَّ أخي في الله دعاك إلى وليمةٍ، وهو يعمل في البنك، هل تُلبي دعوتَه وتأكل من طعامه أو ماذا تفعل؟ وما الفرق بين مَن يعمل في البنوك الربوية ومَن يعمل في شركات التأمين التجاري -كالتأمين على الحياة والسيارات؟ وهل تجاب دعوة مَن يعمل في شركات التأمين التجاري؟ أفيدونا عن ذلك جزاكم الله خيرًا.","title":"ما حكم تلبية دعوة من يعمل بالبنوك والتأمين؟","answer":"الجواب: هذه أمور عمَّت بها البلوى في اختلاط المكاسب، وكثرة الخَبَث، عمَّت بها البلوى في هذا العصر، فينبغي للمؤمن الحذر من المكاسب الخبيثة، والحرص على المكاسب الطيبة، يقول النبيُّ ﷺ: يقول الله : إنَّ الله تعالى طيبٌ لا يقبل إلا طيبًا فينبغي للمؤمن الحذر من المكاسب الخبيثة، ويقول عليه الصلاة والسلام: ما من عبدٍ يتصدق بعَدْل تمرةٍ من كسبٍ طيبٍ -ولا يقبل الله إلا الطيب- إلا تقبَّلها الله بيمينه، فيُربّيها لصاحبها كما يُربي أحدُكم فُلُوَّه أو فصيله، حتى تكون مثل الجبل.\nفينبغي للمؤمن التَّحرز من المكاسب الخبيثة مهما أمكن، كالعمل في البنوك، أو في شركات التأمين، أو ما أشبه ذلك من الطرق التي فيها خُبثٌ، ينبغي له أن يحتاط.\nأما كونه تُجاب دعوته أو كونه يُهجر أو ما أشبه ذلك: هذا فيه كلامٌ لأهل العلم: منهم مَن يستحب عدم إجابة دعوته؛ لأنه حينئذٍ مكسبه خبيث، ومنهم مَن لا يرى ذلك؛ لأنَّ الأصل السلامة، وأنت لا تدري ما قدم لك؟\nوالهجر له مُستحبٌّ؛ لعله ينتفع بالهجرة، ولكن لا يَحْرُم طعامه، وقد قال جماعةٌ من أهل العلم: إن هجران أهل المعاصي سنة مؤكَّدة إذا أظهروها -أظهروا المعاصي-، وقال بعضُهم: يجب هجره حتى يدع المعصية، والنبي ﷺ فعل هذا وهذا، هجر قومًا وترك قومًا.\nفالمسلم إذا رأى المصلحة في الهجر هجر، وإذا رأى المصلحة الشرعية في عدم الهجر وفي مُوالاة النَّصيحة والتَّوجيه والإرشاد فعل، فقد هجر النبيُّ الثلاثة الذين تخلَّفوا عن غزوة تبوك، ولم يهجر عبدالله بن أُبي وجماعة من المنافقين؛ تأليفًا لهم على الإسلام، وحذرًا من فتنةٍ تقع بهجرهم.\nوإذا كان الذي يعمل في البنك أو غيره له أكساب أخرى غير الحرام فالأمر في هذا واسعٌ، يكون الطعام المقدَّم محتمل أن يكون من الكسب الخبيث، ومحتمل أن يكون من الكسب الآخر، فيكون فيه الأمر واسعًا، وأقل خطرًا من الذي ليس له كسبٌ إلا البنك، أو الكسب الآخر الخبيث.\nفإذا تورَّع الإنسانُ ولم يُجب دعوته إذا كان كسبه كله خبيثًا، وبيَّن له: أني ما تركتُ إجابتك إلا لأجل هذا؛ لعله يرتدع، لعله يستجيب؛ هذا حسنٌ من باب الورع، ومن باب التَّعاون على الخير. وإذا كان هجره بذلك قد يترتب عليه مفاسد وشرّ وعداوة وبغضاء وترك للحقّ؛ فليعمل الأصلح، كما فعل السلف، لا بدّ أن ينظر في الأصلح، ويتحرى الأصلح، وهو لا يتيقن أنَّ هذا الطعام من الكسب الخبيث، بل قد يكون من كسبٍ آخر، من دراهم أخرى دخلت عليه غير الكسب الخبيث.\nفالحاصل: أنَّ ترك ذلك إذا كان كسبُه كله خبيثًا، ليس له إلا الكسب الخبيث، ترك الإجابة أوْلى وأحوط، من باب الهجر، ومن باب إظهار كراهة العمل الذي هو فيه؛ لعله يستجيب، لعله يتوب، إلا أن يكون في ترك الهجر مضارٌّ وخطرٌ ديني ومصالح تفوت دينية، فهذا محل النظر من المؤمن، ينظر ويتأمَّل: فإن كانت إجابته أصلح في الدين وأنفع للمسلمين أجاب، وإن كانت عدم الإجابة أصلح، وفيها ردعٌ لهذا العاصي، وفيها دعوةٌ له إلى الخير؛ ترك الإجابة، لعله يستجيب، ولعله ينتفع.","link":"https://binbaz.org.sa/fatwas/21010/ما-حكم-تلبية-دعوة-من-يعمل-بالبنوك-والتامين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0807ما حكم تلبية الوليمة إذا كان صاحب الوليمة يعمل بالبنك الربوي؟ ابن باز فتاوى المحاضرات.mp3","categories":["الزفاف ووليمة العرس"]},{"id":1178,"question":"أحد الباحثين قام بعمل بحثٍ حول الغناء وآلات العزف، وقال: إنَّ رأيه قد استقرَّ على إباحة ذلك كله، فما رأي سماحتكم؟","title":"ما الرد على من يرى إباحة الغناء والمعازف؟","answer":"الجواب:\n\nهذا فيه تفصيل:\n\nأما الشعر العربي المعروف فهذا لا بأس به إذا كان معناه الدَّعوة إلى الله، أو التَّشجيع على الكرم والجود والأعمال الطيبة، أو الجهاد، أو هجو الأعداء، أو الحث على الجهاد، أو نحو ذلك، مثلما كان يفعل حسانُ وكعبُ بن مالك وعبدُالله بن رواحة وغيرُهم، هذا أمرٌ مُسلَّمٌ، وهكذا النَّشيد فيما ينصر الحقَّ، كما كان النبيُّ يفعل والصحابة لما كانوا يحفرون الخندق، وفي بناء مسجده ﷺ:\n\n\n\t\n\t\t\n\t\t\tاللهم لولا أنت ما اهتدينا\n\t\t\tولا تصدَّقنا ولا صلَّينا\n\t\t\n\t\t\n\t\t\tفأنزلن سكينةً علينا\n\t\t\tوثبِّت الأقدامَ إن لاقينا\n\t\t\n\t\n\nهذا كله طيب.\nأما آلات الملاهي أو الغناء المعروف الذي يُشبه غناء النِّساء بالتَّكسر وألحان النساء؛ فهذا محرَّمٌ عند جمهور أهل العلم، ذهب قلَّةٌ إلى جواز الشيء اليسير منه، ولكن الأكثرين من أهل العلم على تحريمه مطلقًا، وإذا كان يدعو إلى خمر أو زنا أو فواحش حَرُم بالإجماع، لكن إذا كانت صيغته تدعو إلى شهوة النِّساء وإلى المعاصي حَرُم ذلك، وإذا كان بأصوات النِّساء حَرُم ذلك؛ لأنَّ الله قال: فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، فيحرم على الرجال سماعه، أما بينهنَّ فلا بأس، بين النساء في العرس لا بأس، كما جاء عن النبي ﷺ، مع الدُّفِّ، أو الجواري في أيام العيد بالأشعار التي لا محذور فيها، كما أقرَّ النبيُّ الجاريتين على الشعر في بيت عائشة، بأشعار الأنصار يوم بُعاث في يوم عيدٍ، وقال: إنه يوم عيد، وأمر الصديقَ قال: دعهما، هذا لا بأس به.\nوقال ابنُ الصلاح: أجمع العلماء على أنَّ الغناء مع بعض آلات اللَّهو مُحرَّمٌ بالإجماع، وإنما الخلاف إذا كان الغناء فقط، ليس معه شيء، الجمهور على تحريمه مطلقًا: الغناء الذي يصدر من النساء، أو من الرجال على طريقة النساء، أما الأشعار العربية بلغة العرب ولحون العرب فهذا جائزٌ ما فيه خلاف، وفعله حسانُ بين يدي النبي ﷺ، وفعله كعب بن مالك، وفعله عبدالله بن رواحة، وهكذا النَّشيد الصالح الذي يدعو إلى الخير بين الرجال، كما فعلوا يوم الخندق، وكما فعلوا في بناء مسجد النبي ﷺ فلا يجوز الخلط والتَّلبيس.\nأما آلات الملاهي فكلها محرَّمة: العود، والكمان، والموسيقى، والطبل، آلات الملاهي ما فيها تفصيل، كلها منكرة، وقد كتبنا في هذا رسالةً مُستقلةً، لها مدة طويلة تُوزَّع، أوضحنا فيها الأدلة بالتفصيل، فنرجو أن تُنشر قريبًا في الصحف؛ لأجل شمول الفائدة، وكذلك تُطبع وتُوزَّع إن شاء الله، هي قد طُبعت مرات كثيرة، ووزِّعَت مرات كثيرة، لكن الحاجة ماسَّة الآن إلى توزيعها في كل مكانٍ.","link":"https://binbaz.org.sa/fatwas/21254/ما-الرد-على-من-يرى-اباحة-الغناء-والمعازف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1140أحد الباحثين قام بعمل بحث حول العناء وآلآت العزف وقال قد استقر على أباحة كله فما رأيكم.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":1206,"question":"إني أحبُّك في الله، أما بعد: كثرت في هذه الأيام الحفلات والزيجات، ولكن مع ذلك كان هنالك ضرب الدُّف والزير عند الرجال، فقال أحدُ الشيوخ أنَّ ذلك حلالٌ في المناسبات، ونحن في ذلك مُحتارون في هذا الأمر، فما الحكم جزاكم الله خيرًا؟","title":"ما حكم ضرب الدف في الأعراس للرجال؟","answer":"الجواب:\nأولًا: أحبَّك الله الذي أحببتنا له. أما الدُّف في الزواج فلا بأس به، أقرَّه النبيُّ ﷺ والصحابة، يعمله النساء، الدف للنساء فيما يتعلق بإعلان النكاح بين النساء خاصةً، من دون اختلاطٍ بالرجال، تضرب المرأة الدف، ويُغنين بالغناء المعتاد، لا بأس بذلك، هذا من إعلان النكاح، أما الطبل فلا، لا يُستعمل الطبل، لا من النساء، ولا من الرجال، لا في العرس، ولا في غيره.\nنسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/21263/ما-حكم-ضرب-الدف-في-الاعراس-للرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1131ما حكم ضرب الدف في الأعراس للرجال؟ ابن باز فتاوى.mp3","categories":["الزفاف ووليمة العرس"]},{"id":1534,"question":"هل هناك فرقٌ بين وليمة الأعراس وغيرها من الولائم؟","title":"ما الآداب المشروعة في الوليمة والدعوة إليها؟","answer":"الجواب:\nالصواب أنَّ الحكم عام، ووليمة العرس أشد.\nس: هل هناك فرقٌ بين الخاصَّة والعامَّة؟ لأنه أحيانًا تكون خاصةً بين الزملاء، أو مثلًا تكون بين الأقارب فيقولون: لا تأتي بأحدٍ معك.\nج: المقصود إذا دُعيت فأجب، إذا دعاك فأجبه، إلا أن تكون الوليمةُ فيها شرٌّ ما يستطيع إنكاره.\nس: الوليمة مثلًا عندي، ويأتون مثلًا بشابٍّ يقول: ما تأتِ بأحدٍ؟\nج: أنت الداعي؟\nس: نعم.\nج: عليك أن تدعو مَن يُناسبه، لا تدعو مَن يشقُّ عليه، إذا كنتَ دعيتَ لزيدٍ فلا تأتِ بأُناسٍ يشقون على زيدٍ، فإذا أتيتَ بمَن يشقُّ على زيدٍ فلم تُكرمه.\nس: ما يبقى فيها فقراء أحسن الله عملك؟\nج: لا تأتِ له بمَن لا يقوى عليه من الفقراء أو من غيرهم إذا شرط عليك؛ في هذه الحالة ألا تدعو أحدًا.\nس: فقد عصى الله ورسولَه هل إذا فعل ذلك عليه أن يتوب؟\nج: عليه التوبة، كل ذنبٍ عليه التوبة منه.\nس: النبي ﷺ يقول: يُرَدُّ عنها الفقراء؟\nج: يعني: بعض الناس قد يدعو الأغنياء ويترك الفقراء، ما أراد الناس كلهم.\nس: المقصود في جوازها، يعني: لم يأتِ ..؟\nج: على حسب الدعوة، لكن الإنسان إذا دعا فليدعُ الفقراء والأغنياء من جيرانه وأقاربه، لا يخصّ الأغنياء، السُّنة أن يدعو الجميع: من أقاربه، من جيرانه، غنيهم وفقيرهم.\nس: لكن لو جاء الفقيرُ أو المسكينُ بدون دعوةٍ؟\nج: الأحسن أنه يُقبَل ويُكرَم.","link":"https://binbaz.org.sa/fatwas/21634/ما-الاداب-المشروعة-في-الوليمة-والدعوة-اليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الوليمة والدعوة إليها والاستجابة للدعوة.mp3","categories":["الزفاف ووليمة العرس"]},{"id":1592,"question":"التَّصفيق للنساء في مناسبة النكاح وغيرها؟","title":"حكم تصفيق النساء في مناسبات الزواج","answer":"الجواب:\nما بلغني فيه شيء، والمقصود هو إعلان النكاح، والتصفيق من شأن النساء، فأمره سهلٌ، التصفيق للنساء، وإعلان النكاح مطلوب.","link":"https://binbaz.org.sa/fatwas/21696/حكم-تصفيق-النساء-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التصفيق للنساء في مناسبة النكاح.mp3","categories":["الزفاف ووليمة العرس"]},{"id":1835,"question":"اتِّخاذ الشعر؟","title":"ما حكم اتِّخاذ الشعر وإطالته؟","answer":"الجواب:\nلا بأس به إذا لم يكن فيه مفسدة، أما إذا اتَّخذه للفساد وتَصَيُّد النساء والفاحشة فيَحْرُم، أما إذا اتَّخذه للتَّسَنُّن وأنه يقصد الخير والسنة فلا بأس.\nس: الشعر الطويل للرجال سُنَّة؟\nج: إذا أخذه بنيةٍ صالحةٍ، ما هو بنية التلاعب والفساد في الأرض.\nس: سُنَّة؟\nج: جائز.\nس: إطالته إطالةً واضحةً؟\nج: ليس هناك حدٌّ محدودٌ، لكن لا يكون قصده خبيثًا.","link":"https://binbaz.org.sa/fatwas/21943/ما-حكم-اتخاذ-الشعر-واطالته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتِّخاذ الشعر وإطالته.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":2855,"question":"بعض الأناشيد فيها طُبُول، هل يعتبر هذا الفعل من فعل الصوفية؟","title":"حكم الأناشيد التي فيها طُبُول","answer":"الجواب: الطَّبْل من آلات الملاهي، ما يجوز.\nس: إذا كان ما فيها شيء، ما فيها طبول؟\nالشيخ: إذا كان ما فيها محذور شرعًا، أشعار عربية تدعو إلى خير أو تأمر بخير؛ ما في بأس، أما إذا كانت أناشيد أو أشعار تدعو إلى الباطل؛ فهي ممنوعة.\nس: يؤدون هذه الأناشيد بإيقاعات موسيقية أشبه بإيقاعات أصحاب الأغاني؟\nالشيخ: المقصود إذا كانت ما فيها محذور؛ لا حرج.","link":"https://binbaz.org.sa/fatwas/23008/حكم-الاناشيد-التي-فيها-طبول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأناشيد التي فيها طبول.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":3434,"question":"اعتاد كثير من الناس في الزواج يرسلون بطاقات دعوة فهل هي ملزمة هذه الأوراق إذا وصلت؟","title":"هل تجب إجابة الدعوة التي تصل بالبطاقات؟","answer":"الجواب: إذا سلم عليه فلا بأس، لا يضر.\nس: يلزمهم الإجابة إذا أُعطوا الكروت هذه؟\nالشيخ: نعم إذا دُعي أحدُكم فلْيُجب.","link":"https://binbaz.org.sa/fatwas/23608/هل-تجب-اجابة-الدعوة-التي-تصل-بالبطاقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تجب إجابة الدعوة إذا كانت عن طريق الكروت.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3481,"question":"يحصل في الحجاز أن بعض الناس يتعمّد عقد نكاح ابنته في الحرم؟","title":"حكم مَنْ تعمّد عقد نكاح ابنته في الحرم","answer":"الجواب: ما أعرف له أصلًا.\nس: لكن هل يُقال: تَقُّصدُ ذلك من البدع؟\nالشيخ: محل نظر، الله أعلم.","link":"https://binbaz.org.sa/fatwas/23658/حكم-من-تعمد-عقد-نكاح-ابنته-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعمد عقد نكاح ابنته في الحرم.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3660,"question":"لو قُدِّر أن الرجال سمعوا (دُفّ النساء)؟","title":"حكم سماع الرجال دُف النساء في النكاح","answer":"الجواب: ولو، ضرب الدف سنة للنساء، ولكن عليهن عدم رفع الأصوات الكثيرة.\nس: لأن بعض الإخوان إذا سمع الدف أنكر؟\nالشيخ: لا، ما دام بين النساء ما يضر، ولو سَمِع من حول الباب؛ لأن هذا من باب إعلان النكاح، ما يكون إعلان إلا بهذا، إذا ما سمعوا وين يكون الإعلان؟ للنساء نعم.","link":"https://binbaz.org.sa/fatwas/23848/حكم-سماع-الرجال-دف-النساء-في-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضرب الدف في النكاح.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3668,"question":"أولم ولو بشاة، الأمر للوجوب للوليمة؟","title":"هل تجب الوليمة في إعلان النكاح؟","answer":"الجواب: يحتمل، الأصل في الأوامر هو الوجوب، والمشهور عند العلماء أنها سنة، الوليمة سنة من باب إعلان النكاح، فليسأل عن نصه، ولعل الصواب أنه ﷺ أولم بغير شاة، أولم لما تزوج صفية بغير اللحم، أولم بالسويق بالتمر واللبن والأقط.\nس: لكن أقصد أصل الوليمة واجبة؟\nالشيخ: من باب إعلان النكاح، والظاهر والله أعلم أنها واجبة، ظاهر النصوص وجوبها؛ لأن هذا من باب إعلان النكاح، إعلان النكاح بالوليمة وجمع ما تيسر من الناس.","link":"https://binbaz.org.sa/fatwas/23856/هل-تجب-الوليمة-في-اعلان-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأمر بالوليمة للوجوب.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3670,"question":"بالنسبة للانصراف بعد الطعام في الوليمة أو غيره، هل تعتبر سنة؟","title":"متى يكون الانصراف بعد إجابة الدعوة؟","answer":"الجواب: هذا السنة فَإِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ [الأحزاب:53] لا يؤذيهم، لا يؤذي أهل البيت، إذا طعم يمشي، إلا على حسب العرف: إذا كان فيه بقية كقهوة أو شاي أو طيب، على حسب العرف، لا بأس، تبع الوليمة. س: هذا عام؟ ج: عام.","link":"https://binbaz.org.sa/fatwas/23858/متى-يكون-الانصراف-بعد-اجابة-الدعوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من السنة الانصراف بعد الطعام.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3671,"question":"قد يُدعى الواحد وهو في الرياض في جدة مثلًا أو مكة، هل تلزمه الدعوة؟","title":"هل يجب إجابة الدعوة إذا كانت هناك مشقة؟","answer":"الجواب: الظاهر أنه إذا كان في مشقة ما تلزم، من دون مشقة.","link":"https://binbaz.org.sa/fatwas/23859/هل-يجب-اجابة-الدعوة-اذا-كانت-هناك-مشقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تلزم إجابة الدعوة للوليمة إذا كانت هناك مشقة.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3672,"question":"الكروت هذه التي توزع في الزواجات، هل هي موجبة للدعوة؟","title":"هل يجب حضور الدعوة باستلام بطاقة لها؟","answer":"الجواب: نعم، إذا جاء الكرت باسمه فهو مدعو.","link":"https://binbaz.org.sa/fatwas/23860/هل-يجب-حضور-الدعوة-باستلام-بطاقة-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في إجابة الدعوة في الوليمة.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3673,"question":"قوله: شر الطعام طعام الوليمة..؟","title":"معنى \"شر الطعام طعام الوليمة\" في الحديث","answer":"الجواب: بهذه الصفة؛ يُدعى إليها الأغنياء ويُمنع منها الفقراء، إذا كانت بهذه الصفة؛ إذا كانت يُدعى إليها الأغنياء ويُترك الفقراء.","link":"https://binbaz.org.sa/fatwas/23862/معنى-شر-الطعام-طعام-الوليمة-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/شر الطعام طعام الوليمة.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3675,"question":"إذا كانت الدعوة فيها منكرات؟","title":"حكم الدعوة التي بها منكر والأوْلى بالإجابة","answer":"الجواب: يحضر من كان يستطيع إنكار المنكر، ومن كان لا يستطيع إنكار المنكر لا يحضر.\nس: قول بن عمر -سلمك الله- وهو صائم..؟\nالشيخ: مثل ما قال ﷺ: إذا دعي أحدكم فليجب، فإن كان صائمًا فليصل، وإن كان مفطرًا فليطعم هكذا رواه مسلم في الصحيح يجيب ولو كان صائمًا، ثم يقول لهم: سامحوني أنا صائم، وينصرف، أو يفطر إذا كان تطوعًا ويأكل معهم.\nس: إذا كان أحد الداعيان قريبًا، والآخر..\nالشيخ: إذا اجتمع داعيان أجيب الأسبق منهما.\nس: ولو كان قريبًا؟\nالشيخ: ولو كان قريبًا، يجيب الأسبق، قريب وإلا ما هو قريب، الأسبق أحق.\nس: التفريق بين دعوة العرس وغير العرس في الوجوب؟\nالشيخ: ظاهر الأدلة الوجوب، وفي الحديث أن عائشة رضي الله عنها قالت: يا رسول الله إذا اجتمع داعيان فإلى أيهما أجب؟ قال: إلى أقربهما منك بابًا، إلى أيهما أهدي؟ قال: إلى أقربك منك بابًا، وفي الحديث: إذا اجتمع داعيان فأقربهما بابًا، فإن سبق أحدهما فأجب الذي سبق، وإن كان في سنده ضعف، ولكن المعنى صحيح، فإذا سبق أحدهما أجيب السابق، فإن استويا فأقربهما بابًا.","link":"https://binbaz.org.sa/fatwas/23864/حكم-الدعوة-التي-بها-منكر-والاولى-بالاجابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في الدعوة إلى وليمة وإجابتها.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3676,"question":"من يقول إن كانت الدعوة دعوة عرس وجبت الإجابة، وإن كانت غير عرس استحبت؟","title":"هل يختص وجوبُ إجابة الدعوة بالعرس فقط؟","answer":"الجواب: ما عليه دليل، وقد تقدم الحديث: من لم يجب الدعوة فقد عصى الله ورسوله.","link":"https://binbaz.org.sa/fatwas/23865/هل-يختص-وجوب-اجابة-الدعوة-بالعرس-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التفريق بين دعوة العرس وغير العرس.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3725,"question":"ضرب الطلقات النارية في الهواء في الأعراس؟","title":"حكم إطلاق النار والطيور إعلانًا للفرح","answer":"الجواب: إذا كان للتعلم لا بأس، ما هو لعب، إذا كان للتعلم والتدرب.\nس: يقول طلق النار في الزواج؟ ليلة الزواج تعمل هذه الطلقات النارية؟\nالشيخ: إذا كان للتعلم تعلم الرمي لا بأس، أما إن كان لإضاعة مال بدون فائدة فهذا لا.\nس: يجعلونه إعلانًا للفرح يطلقون شيئًا من الرصاص؟\nالشيخ: بعض الناس في بعض البلاد الجنوبية قد يفعلون هذا، لكن بلغني الآن أخبرني جماعة من الناس أنه قد يقع فيه شر وقتل، قد يخطئ الرامي، وقد يحصل به قتل، فإذا كان يحصل به شر يجب منعه، على ولاة الأمور إذا كان في بلد يُخشى منه شر يمنع.  أما إذا كان لتعلم الرماية مثل ما فعل الحبشة يتعلمون بالسيوف وبالرماح وبالدرق وبإطلاق الرمي في الهواء من دون مضرة على أحد فلا بأس، أما إذا كان يخشى منه مضرة فعلى ولي الأمر أن يمنعه أينما كان إذا كان فيه مضرة على أحد.\nس: في بعض الزواجات يلقون الطيور...؟\nالشيخ: وأيش السبب؟\nس: يلقون الطيور أمام النساء، حمام وعصافير؟\nالشيخ: تركه أولى، شيء جديد هذا، قد يكون تشبهًا بناس من الكفرة.\nس: هذا هو الظاهر يا شيخ؟\nالشيخ: ينبغي ترك هذا، إذا كان فيه تشبه وجب تركه، ثم أيضًا الحفل فيه إعلان، وجود الحفل ووجود الوليمة يكفي في الإعلان، والحمد لله.","link":"https://binbaz.org.sa/fatwas/23917/حكم-اطلاق-النار-والطيور-اعلانا-للفرح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما يقع في الأفراح من ضرب النار وإطلاق الطيور إعلانًا للفرح.mp3","categories":["الزفاف ووليمة العرس"]},{"id":3968,"question":"قول عامر في شعره: فاغفر فداء لك؟","title":"مَنْ يعني عامرٌ في شعره: فاغفر فداء لك؟","answer":"الجواب: ما فيه شيء، المقاتلون كلهم فداء له ، المقاتل في سبيل الله كذلك؛ لأن المقصود أفدي طاعتك وما شرعت له وما جاء به رسولك ﷺ، فالفداء لله فداء لدينه وفداء لشرعه.","link":"https://binbaz.org.sa/fatwas/24196/من-يعني-عامر-في-شعره-فاغفر-فداء-لك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يخاطب عامر في شعره فاغفر فداء لك.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":4930,"question":"الوليمة عند عقد النكاح أو عند إعلان الدخول؟","title":"هل تكون الوليمة عند عقد النكاح أو الدخول؟","answer":"الجواب: عند الدخول، الوليمة إذا دخل بالمرأة.","link":"https://binbaz.org.sa/fatwas/27021/هل-تكون-الوليمة-عند-عقد-النكاح-او-الدخول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تكون الوليمة عند عقد النكاح أو الدخول.mp3","categories":["الزفاف ووليمة العرس"]},{"id":5129,"question":"سائل يقول: لقد درجت وشاعت بعضُ العادات عند القبائل بإحضار مَن يُسَمَّون: شُعراء المحاورة، مثل: أن يأتوا بشاعرين في حفلات العُرس ونحوها، كل واحدٍ منهما من قبيلةٍ، مقابل إعطائهما مبلغًا من المال، ويقوم الشاعران بإحياء الليل كما يقولون، حيث يكون هناك صفَّان مُتقابلان من الرجال، وكل شاعرٍ له صفٌّ، يُرددون ترديدًا جماعيًّا ما يقوله الشَّاعران، بأصواتٍ عاليةٍ، مع التَّصفيق والرقص والتَّمايل، ويفتخر كل شاعرٍ بحسبه ونسبه، ويطعن بالمُقابل في الشاعر الآخر، فما الحكم في هذا كله؟","title":"ما حكم إحضار شُعراء المحاورة في الأعراس؟","answer":"الجواب: أمَّا الغناء في العُرس من النِّساء بالدُّفوف فهذا من إعلان النكاح، فمشروعٌ ضرب الدف في النكاح للنساء خاصةً، وليس فيه اختلاطٌ، ويكون بالأغاني العادية التي ليس فيها منكر، فهذا مشروعٌ للنساء، وهو من إعلان النكاح، وكان يُفْعَل في عهد النبي ﷺ ويحضره أزواجُه وغيرُهم. أما الرجال فلا بأس أن يتعاطوا الشعر العربي، ويجتمعوا عليه ويسمعونه، وهو الذي ليس فيه محذور، ليس فيه غيبة، ولا سبٌّ، ولا شتمٌ، ولا يُسبب الشَّحناء والعداوة، بدون طبلٍ، وبدون أي منكرٍ آخر من: عيب الناس، أو عيب قبيلة فلان مما يُسبب الشَّحناء، فهذا لا يجوز، أما إذا حضَّروا شعرًا طيبًا: كشعر حسان، والأشعار الطيبة، والقصائد الطيبة التي فيها الخير والدَّعوة إليه، أو قام شاعرٌ يدعوهم إلى الخير: إلى الجود والكرم والأعمال الطيبة، وقام شاعرٌ آخر كذلك يدعو إلى الخير ومكارم الأخلاق ومحاسن الأعمال؛ فلا بأس، وكما قال ﷺ: إنَّ من الشعر لحكمةً، وقال لحسان: اهجُ الكفار، فوالذي نفسي بيده، إنه لأشدّ عليهم من وقع النَّبْل، وقال: اللهم أيِّده بروح القدس، فكان حسانُ يهجوهم، وكانت أشعاره عظيمةً طيبةً، وهكذا عبدالله بن رواحة، وكعب بن مالك، وهكذا مَن بعدهم من الشُّعراء الطيبين. ومن الشعر: \"نونية ابن القيم\" التي هي من أعظم الشعر وأنفعه، فهي قصيدة طيبة عظيمة نافعة، و\"نونية القحطاني\"، وهي قصيدة طيبة نافعة في العقيدة، وهكذا الأشعار الطيبة التي فيها الدَّعوة إلى الخير وإلى مكارم الأخلاق ومحاسن الأعمال، فهذا طيبٌ في العرس وغير العرس. أما أن يقوم شاعران أو أكثر يتناحرون، ويذمّ بعضُهم بعضًا، ويسبُّ بعضُهم بعضًا هذا منكر، أو يسبُّ هذا قبيلةَ هذا، وقبيلةَ هذا؛ هذا منكر، لكن إذا كان الشعرُ فيما ينفع الناس؛ كالدَّعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وبرّ الوالدين، وصلة الرحم، وطاعة الله ورسوله، وطاعة ولاة الأمور بالمعروف، والحذر من معاصي الله؛ فهذا كله طيبٌ، وله أثرٌ في النفوس. ولا بأس أن تُعطى المغنية في العُرس أجرةً على عملها، أو الشاعر الذي عنده أشعار طيبة، فيُدْعَى ليقول الشعر الطيب الذي ينفع الناس، ويُعْطَى جائزةً، لا بأس بذلك. أما الذي يدعو إلى غيبة فلان، وذمِّ فلان، ومدح فلان؛ لإثارة الشَّحناء والعداوة والبغضاء بين الناس، فهذا منكرٌ لا يجوز -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/30044/ما-حكم-احضار-شعراء-المحاورة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 65.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5170,"question":"هذه مجموعة أسئلة تسأل عن العرضة، وحكم إعطاء المال للشعراء، وأسئلة أخرى تسأل عمَّا يُسمَّى بشعر الرد، يعني: بدون عرضة؟","title":"حكم \"العرضة\" والطبول وإعطاء المال للشعراء","answer":"الجواب: العرضات إذا كانت لا تمنع من الصلاة ولا تشغل عنها، وليس فيها اختلاط الرجال بالنساء، وفيها اختلاط بالرجال خاصةً، وليس فيها ما يُنْكَر، بالأشعار العربية، أشعار تدعو إلى الجود والكرم والحماس والشجاعة ونحو ذلك، وليس فيها منكر: لا موسيقى، ولا طبول؛ فلا بأس. أما إذا كانت فيها موسيقى وآلات ملاهٍ من طبول وموسيقى، وكانت تشغل عن الصلاة، أو فيها محذورات أخرى، منكرات أخرى: من كشف عورات؛ لا تحضر، لا يجوز حضورها، إلا إذا كانت سليمة: أشعار سليمة، ومجالس سليمة، ولا تشغل عن الصلاة، وليس فيها من آلات اللهو شيء، لا بأس. س: التطبيل يا شيخ؟ الشيخ: الطبل لا يصلح، وفي الحديث الصحيح يقول ﷺ: إن الله حرَّم عليكم الخمرَ والميسرَ والكوبة، قال الراوي: والكوبة هي الطبل.","link":"https://binbaz.org.sa/fatwas/30095/حكم-العرضة-والطبول-واعطاء-المال-للشعراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 120.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5286,"question":"طالبات في حفل مدرسي أو في فرح ينشدن الشعر بشكل جماعي من أجل تقوية الصوت فقط، وهذا النشيد بعيد عن التلحين الغنائي فما الحكم في ذلك، وهل هناك فرق بين النشيد الجماعي والنشيد الفردي؟","title":"هل يجوز النشيد بصوت جماعي للفتيات؟","answer":"الجواب: النشيد طيِّبُه طيب، وخبيثُه خبيث، إن كان يتضمن الدعوة إلى الخير وإلى الإصلاح وإلى التقوى فهو مثل الشعر إن من الشعر حكمة وإن كان نشيدًا فيه أشياء منكرة صار مذمومًا كالشعر المذموم، يقول ﷺ: إن من الشعر حكمة، وكان ﷺ يسمع شعر حسان؛ لأنه شعر يدعو إلى طاعة الله واتباع شريعته وتصديق النبي ﷺ، وابن رواحة، وابن أبي أوفى، وكعب بن مالك، وغيرهم؛ لأنها أشعار مفيدة. أما الأشعار التي تدعو إلى الباطل أو تثبِّط عن الطاعات أو تدعو إلى الفحش فهي محرّمة، وهكذا النشيد إن كان على خير فهو طيب، وإن كان على شر فهو مذموم. السؤال: بشكل جماعي؟ الشيخ: أما إذا كان للتعليم كونه يعلّمهم ويقرؤون جميعًا؛ لا بأس من باب التعليم أما التعبد بذلك لا، ما هو مشروع ... ولا في الأذكار ولا في غيرها، كُلٌّ يذكر الله على حسب حاله من غير رفع صوته على الآخر، لكن يذكر الله على حسب التيسير .. أما المعلم إذا كان معه أربعة أو خمسةحتى يتقنوا ما يقول لهم من باب التعليم؛ فلا بأس ولا حرج في ذلك.[1]","link":"https://binbaz.org.sa/fatwas/30924/هل-يجوز-النشيد-بصوت-جماعي-للفتيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 005.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":7207,"question":"بيني وبين أخي خصام حول إحضار القينات المغنيات في زواج لنا، وحجته أن هذا من باب إعلان الزواج، مع العلم أنه بعيد عن السنة، وتعلمون سماحتكم ما يرافق هذه القينات من الغناء الفاحش والاختلاط والتصوير وغيره، نرجو بيان وجه الحق والفصل بيننا، وجزاكم الله خير الجزاء؟","title":"حكم إحضار المغنيات بحجة إعلان النكاح","answer":"الجواب:\n\nالمشروع في الزواج إعلانه وإظهاره، وأن يكون فيه إعلان يجتمع النساء مع النساء والرجال مع الرجال؛ لأن الرسول ﷺ أمر بإعلان النكاح، وكان يفعل في عهد النبي ﷺ يجتمع النساء إلى أهل العروس، ويزفونها إلى زوجها، ويكون بينهم بعض الأغاني العادية، الوطنية، في مدح الزوج، ومدح أهل الزوج، أو مدح الزوجة، وأهلها، وما أشبه ذلك.\n\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم \n\t\t\t فحينونا نحييكم\n\t\t\n\t\n\n\nإلى غير ذلك، هذا شيء لا بأس، أما الأغاني المنكرة التي فيها مدح الخمور، أو الدعوة إلى عشق النساء، أو عشق الرجال، أو رفع هذا بمكبرات الصوت، هذا كله منكر، أما الغناء العادي بين النساء وحدهن من دون اختلاط في محلهن، من دون مكبرات ولا اختلاط بين النساء، الغناء العادي لا بأس، هو من إعلان النكاح كما كان في عهد النبي ﷺ كما كان أزواج النبي يحضرنه -عليه الصلاة والسلام-.\n\nالسؤال: والرجال؟\n\nالجواب: وأما الرجال فلا، الرجال لا يجوز لهم أن يختلطوا مع النساء، أما لو كانوا وحدهم في السلاح، بالرمي، بالأشعار العربية التي ما فيها شر، ولا فيها طبول، ولا شيء؛ لا بأس، يكونون وحدهم بعيدين عن النساء كما يفعل بعض الناس، يرمون وقت الزواج لإعلان النكاح بالرمي، ويجتمعون على قصائد جيدة، فيها حماس، والدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، والشجاعة، ويتعلمون الرمي بحمل السلاح، ما نعلم في هذا بأسًا. \n\nفقد فعل هذا الحبشة في مسجد النبي ﷺ كانوا يلعبون بالحراب في المسجد، والنبي ينظر إليهم، فهذا لا بأس به، كما أقره النبي ﷺ، إذا كان من هذا الطريق مما يتعلق بالحماس في تعلم الشؤون الحربية وكيف يحذف الرمح؟ وكيف يحمل الحربة؟ وكيف يرمي بالبندق؟ وكيف يحمل السيف؟ إلى غير ذلك، هذا شيء ينفع الجميع، أما مع اختلاط النساء فلا يجوز، أو مع الطبول كذلك، أو مع أغاني منكرة تتعلق بالنساء، أو شؤون النساء، أو جمال النساء، أو دعوة إلى فسوق وعصيان، أو خمور، أو أشياء هذا ينكر، يمنع.","link":"https://binbaz.org.sa/fatwas/3272/حكم-احضار-المغنيات-بحجة-اعلان-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1598.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":7408,"question":"أحب أن أحيط سماحتكم أنه قد ظهر في المجتمع السعودي ظاهرة مخترعة وسيئة جدًا، ومنكر شنيع وفظيع، وهو ما يسمونه بالشرعة بمناسبات الزواج، حيث يأتون بالرجل المتزوج ويدخلونه على النساء بعد أن يغطون العروسة... أمام النساء، ويأتي الرجل ويكشف الشرعة؟","title":"حكم ما يسمى بالشرعة في مناسبات الزواج","answer":"الجواب: هذه معروفة، هذه نبهنا عليها، وكتب لوزير الداخلية في ذلك، وعمم بذلك -نسأل الله أن يهدي الجميع- لا شك أن هذا العمل سيئ؛ لأنه يدخل الرجل على النساء مكشوفات سافرات، وربما فعل مع زوجته شيئًًا لا يناسب بحضرتهن ورؤيتهن، هذا لا يجوز، قد نُبه على هذا - ونسأل الله أن يهدي الجميع-.","link":"https://binbaz.org.sa/fatwas/3498/حكم-ما-يسمى-بالشرعة-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1802.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":7422,"question":"أحب أن أحيط سماحتكم أنه قد ظهر في المجتمع السعودي ظاهرة مخترعة وسيئة جدًا، ومنكر شنيع وفظيع، وهو ما يسمونه بالشرعة بمناسبات الزواج، حيث يأتون بالرجل المتزوج ويدخلونه على النساء بعد أن يغطون العروسة... أمام النساء، ويأتي الرجل ويكشف الشرعة؟","title":"حكم ما يسمى بالشرعة في مناسبات الزواج","answer":"الجواب: هذه معروفة، هذه نبهنا عليها، وكتب لوزير الداخلية في ذلك، وعمم بذلك -نسأل الله أن يهدي الجميع- لا شك أن هذا العمل سيئ؛ لأنه يدخل الرجل على النساء مكشوفات سافرات، وربما فعل مع زوجته شيئًًا لا يناسب بحضرتهن ورؤيتهن، هذا لا يجوز، قد نُبه على هذا - ونسأل الله أن يهدي الجميع-.","link":"https://binbaz.org.sa/fatwas/3498/حكم-ما-يسمى-بالشرعة-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1802.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":7473,"question":"أيضاً يقول: هناك بعض الآباء يتجاوزون في المهور، نريد أن توجهوا لهم النصيحة لعل الله  أن يهديهم في ذلك.","title":"حكم المغالاة في المهور والولائم","answer":"الجواب: هذا أمر عام ومصيبة كبيرة، وهي المغالاة في المهور، ونصيحتي لكل مسلم أن يدع ذلك، وأن يحذر المغالاة في مهر بنته أو أخته أو قريبته الأخرى، وأن يتساهل في ذلك ويرضى بالمهر المناسب الذي يعين المرأة على حاجاتها المعروفة، ولا يكون فيه إرهاق للزوج ولا منع للنكاح، هذه الكل يشكو منها، مسألة المغالاة في المهور، والمغالاة أيضاً في الولائم، كلتاهما ضارتان، فينبغي للأولياء وللنساء أيضاً أن لا يشددوا في ذلك بأن ترضى المرأة وأمها وقراباتها بالشيء المناسب، كما يرضى الأب وبقية الأولياء بذلك، بعض الأحيان قد يكون الأب يرضى أو الولي لكن لا ترضى أمها وأختها ونحو ذلك، وربما حملته أمها على المغالاة.\nفالحاصل: أن هذا مطلوب من الجميع؛ مطلوب من الأم والخالة والبنت نفسها، مطلوب من الأب، مطلوب من الإخوة، مطلوب من الأجداد، كلهم يتعاونون في تسهيل المهور وعدم المغالاة حتى يتيسر تزويج قريباتهن. أما مع المغالاة فإن البنت تبقى حبيسة البيت ولا يتقدم لها إلا القليل من الناس، ليس كل واحد عنده القوة على المهر المرتفع، ثم هذا لا ينبغي لأن المغالاة في المهور تفضي إلى فساد كبير، إلى تعطيل البنات والأخوات، وتعطيل الشباب، والوقوع في الفواحش، هذا كله شره عظيم وعاقبته وخيمة. كذلك الولائم ينبغي ألا يعني يتنافس فيها، بدل ما يذبح عشر ذبائح خمسة عشر يكتفي بواحدة أو ثنتين أوثلاث، بدل ما يدعو مائة مائتين يدعو خمسة، عشرة من أقاربه الأدنين ويكتفي بذلك حتى تكون النفقة أقل، وحتى يستطيع أن يتقدم للزواج، لكن إذا ذكر أن هناك ولائم تحتاج إلى ألوف بل عشرات الألوف مع مغالاة المهر، فإن هذا كله يسبب تعطيل الرجل وتعطيل البنت جميعاً، ولا حول ولا قوة إلا بالله، نسأل الله للجميع الهداية. نعم.","link":"https://binbaz.org.sa/fatwas/4316/حكم-المغالاة-في-المهور-والولاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00303.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":8048,"question":"يقولون: إن للزواج صلاة ويسمونها: سنة أو سنة الزواج، وهي قبل الدخول، أي قبل المجامعة ويقولون: تصلى ركعتين، أو تصلي ركعتين، ومن بعدها الدخول أفيدونا مشكورين؟","title":"حكم صلاة ركعتين قبل الدخول على الزوجة ليلة الزفاف","answer":"الجواب: يروى في ذلك بعض الآثار عن بعض الصحابة، صلاة ركعتين قبل الدخول، ولكن ليس فيها خبر يعتمد عليه من جهة الصحة، وإذا صلى ركعتين كما فعل بعض السلف فلا بأس، وإن لم يفعل فلا بأس، فالأمر في هذا واسع، ولا أعلم في هذا سنة صحيحة يعتمد عليها. نعم.","link":"https://binbaz.org.sa/fatwas/5846/حكم-صلاة-ركعتين-قبل-الدخول-على-الزوجة-ليلة-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_081/08112.mp3","categories":["الزفاف ووليمة العرس"]},{"id":8697,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة يقول: (ع. ع. ع) أخونا يشكو سماحة الشيخ من بيوت الأفراح ومن المغالاة فيها ولاسيما وأن كثيراً من الناس اتخذها عادة ويشترط لزواج ابنته أن يكون فرحها في البيت الفلاني، وهي تثقل كاهل العريس، ويرجو التوجيه حول هذا الموضوع؟","title":"الحث على ترك التكلف في أمور الزواج","answer":"الجواب: لا ريب أن السنة عدم التكلف في المهور والولائم من أجل تسهيل زواج الشباب والفتيات، فينبغي لأهل الزوج ولأهل الزوجة عدم التكلف في هذه الأمور، وأن يتواصوا بترك التكلف، وأن يتواصوا أيضاً بقلة المهور تشجيعاً للشباب على الزواج وحرصاً على تزويج الفتيات وعدم بقائهن في البيوت، وقصور الأفراح كذلك مما يثقل كاهل الزوج أو أهل الزوجة في بعض الأحيان، وكذلك كثرة الولائم والتوسع في الوليمة يشق عليهم أيضاً.\nفالمشروع للجميع عدم التكلف لا لأهل الزوج ولا لأهل الزوجة، المشروع للجميع عدم التكلف، خير الصداق أيسره خيرهن أقلهن مئونة، فينبغي للمؤمن أن لا يتكلف في هذه الأمور، ولكن يفعل السنة، النبي عليه السلام قال لـعبد الرحمن بن عوف: أولم ولو بشاة، والنبي ﷺ أولم على زينب بخبز ولحم ودعا الناس إلى الوليمة، فكل من دخل أكل.\nفالمقصود: أن جنس الولائم مشروعة في النكاح لكن ينبغي للمسلمين في هذا عدم التكلف بالاستكثار من الولائم وجعل الطعام الكثير الذي قد يفضي إلى جعله في القمائم والمحلات التي قد ينبغي تنزيه الطعام عنها وبعده عنها وأن يبعث إلى الفقراء والمحاويج.\nالمقصود أن كثرة الولائم تفضي إلى هذا، تفضي أن يلقى الطعام واللحوم في الزبالات والقمائم أو في محلات يرغب عنها مع حاجة الفقراء إلى هذا المال وهذا الطعام الذي دعت الحاجة إلى وضعه في القمامة لعدم علم بعض الناس بالفقراء أو عدم قدرته على الوصول إليهم.\nفالحاصل أن التسامح في هذا وعدم التكلف هو الذي ينبغي لأهل الزوج والزوجة جميعاً، لكن إذا دعت الحاجة إلى قصر؛ لأن ليس عنده بيت يستطيع فيه الزواج فالأمر في هذا واسع، لكن لا ينبغي التكلف ينبغي أن يكون القصر خفيف المئونة، المحل يلتمسون الشيء الخفيف المئونة حتى لا يقع التكلف، وإذا اكتفوا بقصورهم ولم يتكلفوا في دعوة الكثيرين من الناس فالأمر في هذا أوسع وأحسن، والحمد لله.\nالمهم إعلان النكاح، فإذا أعلنوه ولو بشاة واحدة أو شاتين في بيوتهم ودعوا بعض الناس الذين يعز عليهم دعوتهم ويحبون دعوتهم في محلاتهم وبيوتهم ولم يتكلفوا فهذا أكمل وأفضل حتى لا يكون هناك مشقة على أحد، وحتى لا تتعطل البنات ولا يتعطل الشباب، نسأل الله للجميع الهداية والتوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6844/الحث-على-ترك-التكلف-في-امور-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13104.mp3","categories":["الزفاف ووليمة العرس"]},{"id":8698,"question":"الواقع سماحة الشيخ الكثير تزوج بدون بيت أفراح وأصبحت بيوت الأفراح مكان للتجارة وأصبحت أيضاً جزءاً من المهر أو من مئونة المهر، ولا أدري عن رأي سماحتكم في الدعوة إلى الاستغناء عنها وإغلاقها لكونها أصبحت باباً من أبواب التجارة وأيضاً تشكل عبئاً على أولئك الذين يريدون أن يستروا دينهم؟","title":"دعوة للنظر في مسألة بيوت الأفراح ومنعها","answer":"الجواب: على كل حال هي لو عدمت ولم توجد استغنى الناس عنها واستراح الناس من التكلف، لكن إغلاقها الآن بعد وجودها هو محل نظر، حتى يحتاج إلى دراسة من ولاة الأمور وأهل العلم دراسة وافية حتى يرى ما هو الأصلح؛ لأن بعض الناس قد يضطر إلى شيء منها لأسباب كثيرة تحملهم على هذا الشيء، لكثرة أقاربهم ومشقة ترك دعوتهم في الزواج والمناسبة، فيضطرون إلى أن يستأجروا شيئاً من بيوت الأفراح لهذا الغرض؛ لأنهم يعلمون أن إعلان النكاح مطلوب ويريدون دعوة أقاربهم ومن يعز عليهم من جيرانهم وليس عندهم بيوت تصلح لذلك من أجل هذا قد يحتاج إلى هذه القصور، ولو عدمت لتعبروا، لاكتفوا بشيء قليل وتعبروا، لكن وجودها صار سبباً للتكلف، والله المستعان. نعم.\nالمقدم: ندع هذا الموضوع لعل الله سبحانه وتعالى يفتح عليكم سماحة الشيخ وتناقشونه إن شاء الله ويوجد له الحل، فالكثير يشكو منه.\nالشيخ: نعم، الله المستعان، نسأل الله التيسير، نسأل الله التيسير. نعم.","link":"https://binbaz.org.sa/fatwas/6845/دعوة-للنظر-في-مسالة-بيوت-الافراح-ومنعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_131/13105.mp3","categories":["الزفاف ووليمة العرس"]},{"id":8894,"question":"أخونا يسأل أيضاً ويقول: ما حكم الدين في قراءة القرآن الكريم ليلة الزفاف، وما هي الآداب الشرعية والسنة النبوية المتبعة في قضاء ليلة الزفاف؟","title":"آداب الزفاف","answer":"الجواب: لا أعلم فيها شيئاً يعني واضحاً يروى عن بعض السلف أنه كان يصلي ركعتين إذا دخل على أهله قبل أن يتصل بهم، ولكن لا أعلم به حديثاً صحيحاً يعتمد عليه، وإذا صلى فلا حرج اقتداءً ببعض السلف يصلي ركعتين ويدعو الله أن الله يجمع شمله بها على خير، وأن يجعلها عون له على طاعته ويبارك له فيها، هذا لا بأس به وهو حسن إن شاء الله، وكذلك يستحب له كما جاء في الحديث: إذا أخذ بناصيتها يقول: اللهم إني أسألك خيرها وخير ما جبلتها عليه، وأعوذ بك من شرها وشر ما جبلتها عليه هذا جاء في الحديث إذا استجد .... حيوانًا، أو تزوج امرأة وقال هذا يرجى فيه الخير إن شاء الله، دعاء حسن اللهم إني أسألك خيرها وخير ما جبلتها عليه، وأعوذ بك من شرها وشر ما جبلتها عليه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7050/اداب-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_140/14007.mp3","categories":["الزفاف ووليمة العرس"]},{"id":9214,"question":"أختنا تسأل وتقول: هل للمسلم أن يلبي دعوة شخص مرابي يتعامل بالحرام دعاه إلى وليمة مع علمه بذلك؟","title":"حكم إجابة وليمة من يتعامل بالربا","answer":"الجواب: إذا كان الداعي ممن يتعاطى الحرام ومأكله ومشربه من الحرام فلا ينبغي أن يجاب؛ لأن هذا فيه تساهل وإقدام على شيء من الحرام، أما إذا كان، لا، له دخل آخر من الحرام والحلال، فهذا يجوز؛ لأنك لا تدري هل المقدم حرام أو حلال، فأصحاب الدخول المختلفة التي فيها الحلال والحرام أمرهم أوسع، ولكن إذا ترك الإنسان ذلك من باب التأديب ومن باب النصيحة ومن باب الإنكار، لعله يستجيب لعله يترك ما حرم الله عليه؛ فهذا حسن ولا سيما إذا كان الترك لا يترتب عليه فوات مصلحة عظمى ولا حصول مفسدة كبرى، فأما إذا كان حضوره في هذا الطعام المشتبه يتضمن مصلحة ودعوة إلى الخير وإنكارًا للمنكر وتعليمًا للخير فحضوره أولى وأنفع في هذه المسألة؛ لأن المال مشتبه ومختلط. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7374/حكم-اجابة-وليمة-من-يتعامل-بالربا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18205.mp3","categories":["الزفاف ووليمة العرس"]},{"id":9254,"question":"إذا كانت الدعوة لحضور حفل الزواج تكلف المدعوة مبالغ كبيرة من أجل ملابسها وزينتها، فهل الأفضل تلبية الدعوة مع تلك التكاليف أو أبقى في منزلي إلى وقت آخر ثم أصل للمباركة فقط، التكاليف تصل إلى مبالغ خيالية.. الواقع سماحة الشيخ ذكرتها، أرجو أن تتفضلوا بالمعالجة؟","title":"حكم عدم إجابة الدعوة إذا كان فيها مشقة","answer":"الجواب: الرسول عليه الصلاة والسلام أمر بإجابة الدعوة، وقال عليه الصلاة والسلام: للمسلم على المسلم ست خصال منها: أن يجيبه إذا دعاه، وقال: من لم يجب الدعوة فقد عصى الله ورسوله، فإجابة الدعوة لوليمة العرس أو لغيرها من الولائم السليمة أمر مشروع، فإذا كانت إجابة الدعوة تكلف المدعو شيئًا يشق عليه فهذا عذر شرعي، كأن تكون المسافة طويلة يحتاج معها إلى سيارة وإلى كلفة، أو تحتاج إلى ملابس لا يستطيعها بل تشق عليه، أو إلى أشياء أخرى في عرف الناس تشق عليه فهذا عذر شرعي، أما إن كانت لا تكلف شيئًا يشق عليه وإنما ملابس عنده يلبسها كالعادة فهذا ليس بعذر، تلبس الملابس أو يلبس الملابس الرجل ويذهب كعادته كما يلبس الملابس يوم الجمعة ويوم العيد، فيلبس الملابس المناسبة لهذه الوليمة، وتلبسها أيضاً كذلك وتجيب الدعوة إذا كان محل الدعوة ليس فيه منكر، أما إذا كان محل الدعوة فيه منكر كوجود أغاني منكرة أو سينما منكرة أو أشياء غير ذلك مما ينكر من آلات الملاهي وضرب العود وأشباه ذلك مما هو منكر في الشرع أو اختلاط الرجال بالنساء فهذا كله يمنع إجابة الدعوة، أما الشيء العادي مثل ضرب الدف والأغاني المعتادة في النكاح بين النساء خاصة فهذا لا بأس به ولا حرج فيه.\nالمقصود والضابط: إن كان هناك منكر لا يزول بحضورها أو بحضوره فهو عذر شرعي في عدم الحضور، فأما إن كان هذا المنكر يزول بحضور المدعو أو بحضورها؛ لأنها تنكره أو لأنهم يهابون حضوره أو حضورها فيدعون المنكر فإن الواجب الحضور حينئذ لإزالة المنكر مع إجابة الدعوة. نعم.\nالمقدم: جزاكم الله خيراً، إذا كانت أختنا ترى في هذه الملابس وفي هذه الزينة حد الإسراف؟\nالشيخ: لا تسرف من أجلهم، الإسراف لا يجوز، وهو الزيادة عن الحاجة المطلوبة والمناسبة، والتبذير: هو صرف المال في غير وجهه، والإسراف: الزيادة، فإذا كان هناك إسراف متحقق لا يليق فليس ذلك جائزاً لها وليس لها فعله من أجل هذه الدعوة، وإنما تلبس الملابس المعتادة في حليها أو في ملابسها المعتادة لأمثالها فقط.\nالمقدم: لأمثالها؟\nالشيخ: نعم.\nالمقدم: طيب.","link":"https://binbaz.org.sa/fatwas/7416/حكم-عدم-اجابة-الدعوة-اذا-كان-فيها-مشقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15303.mp3","categories":["الزفاف ووليمة العرس"]},{"id":9408,"question":"أنا مقبل على الزواج، ولكن يمنعني من ذلك أسلوب الزواج عندنا حيث أنه لابد أن تقام حفلة العرس لمدة يومين بما تحويه من غناء فاحش ورقص ولهو واختلاط بين الرجال والنساء، ولا شك أن هذا منافٍ للدين، وكل من أراد الزواج من الشباب لابد من فعل هذا وإلا سوف لن يجد من يرضى به، فماذا يجب علي أن أفعل في مثل هذا الحال؟ وما هو الحد المشروع من اللهو والغناء؟ وهل الضرب على الطبول مشروع؟ وهل يتحتم علي السفر إلى بلاد أخرى بحثًا عن زوجة صالحة وطريقة إسلامية في الزواج؟ صاحب هذا السؤال هو أخونا منذر (أ. أ) من ليبيا؟","title":"ما حكم المنكرات في حفلات الزواج؟","answer":"الجواب: لا ريب أن كثيرًا من الناس لا يتقيد بالمشروع في الزواج ولا في غيره، والواجب على المسلمين أن يتقيدوا بشرع الله في الزواج وفي غيره أينما كانوا، في المملكة العربية السعودية أو في ليبيا أو في المغرب الأقصى أو في الجزائر أو في تونس أو في أي مكان، الواجب على أهل الإسلام التقيد بالأمر الشرعي، وأن يتواصوا بذلك وأن يتعاونوا عليه، كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] ، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].\nفلابد من التواصي بالحق ولابد من التواصي بالصبر في أمر الزواج وغيره، وفي جميع الأمور التي تقع بين المسلمين، فيتعاونون في إقامة الصلاة في الجماعة، وفي أداء الزكاة، وفي صيام رمضان وحفظه عما حرم الله، وفي أداء الحج مع الاستطاعة، وفي بر الوالدين، وفي صلة الأرحام، وفي ترك الغيبة والنميمة وسائر المعاصي، وفي ترك الكذب وشهادة الزور، وفي ترك ظلم الناس في الأموال والأعراض والدماء إلى غير ذلك ، الواجب على أهل الإسلام أينما كانوا ذكورًا كانوا أو إناثًا أن يتقوا الله، وأن يتعاونوا على طاعة الله ورسوله، وأن يتعاونوا أيضًا على ترك ما حرم الله ورسوله، وبذلك تحصل لهم السعادة والنجاة في الدنيا والآخرة.\nومن هذا أمر الزواج، يجب أن يكون الزواج على الطريقة الشرعية ليس فيه تكلف ولا إسراف ولا تبذير، بل يجب القصد في كل شيء، وعدم التكلف حتى يكثر الزواج، وحتى يحصل عفة النساء والرجال جميعًا، فالشباب بحاجة إلى الزواج، والنساء كذلك في حاجة إلى الزواج.\nوالتكلف هو تعاطي ما حرم الله من المنكرات، كل هذا مما يسبب تعطيل النكاح، وبقاء الشباب والفتيات من دون زواج.\nفلا يجوز اختلاط الرجال بالنساء في الأعراس، ولا في غيرها، بل يجب أن يكون النساء في محل خاص على حدة، والرجال على حدة، وأن تكون الوليمة مقتصدة ليس فيها تكلف ولا شيء يشق على الزوج وآل الزوجة، بل يتحرون جميعًا الاقتصاد وما يكفي المدعوين، ويقتصدون أيضًا في الدعوة التي لا تشق عليهم.\nوهكذا يشرع لهم الاقتصاد في المهور وعدم التكلف، وأن يسهلوا في المهور حتى يحصل النكاح وحتى يكثر الزواج بين الناس.\nومن ذلك أيضًا: مسألة الطرب فلا بأس أن تتعاطى النساء الدف يعني: الطار المعروف وهو ذو الوجه الواحد، يضربه النساء بينهن بصفة خاصة في محل خاص ليس فيه اختلاط الرجال، ولا مانع من الأغاني العادية التي ليس فيها محذور شرعًا التي بين النساء في بيت الزوج أو الزوجة أو أهل الزوج أو أهل الزوجة ونحو ذلك، كما كان يفعل في عهد النبي ﷺ وعهد أصحابه، وكان نساء النبي ﷺ يحضرن الأعراس، ويحضرن الغناء العادي والاحتفال العادي، كل هذا لا بأس به.\nأما وجود المطربات والأصوات العالية بالمكبرات التي تشغل الناس وتؤذي الجيران والمارة، ويعلن فيها الأغاني المحرمة هذا لا يجوز.\nوهكذا السهر الذي يضيع على الناس صلاة الفجر ويسبب ترك الصلاة التي أوجب الله، فهذا كله لا يجوز.\nوهكذا إيجاد آلات الملاهي من العود وأشباهها من آلات اللهو والطبول كل هذا لا يجوز.\nإنما يباح الطار المعروف وهو الدف فقط للنساء بشرط أن يكون خاليًا ليس فيه ما يسبب الفتنة من حلقات مزعجة أو أشياء مزعجة، بل الدف العادي وهو الطار العادي المعروف تضربه المرأة وتغني الأغاني القليلة المعتادة بينهن نصف ساعة أو ساعة ونحو ذلك ثم ينصرفن في أول الليل، ولا يسهرن إلى آخر الليل أو إلى معظم الليل؛ لأن هذا يضر الجميع، ويسبب النوم عن الصلاة من الجميع.\nفالحاصل: أن الواجب على جميع المسلمين في كل مكان أن يتحروا في زواجهم ما شرع الله، وأن يبتعدوا عما حرم الله، وأن يتواصوا بعدم التكلف لا في المهور، ولا في الولائم، ولا في دعوة الناس الكثيرين الذين يسببون المشاكل، ولا في إيجاد المطربات من طريق مكبرات الصوت، ولا إيجاد آلات الملاهي غير مجرد الدف والأغاني العادية لوقت مناسب من الليل ينتهي من دون طول ومن دون مشقة ومن دون السهر أكثر الليل أو كل الليل، هذا الواجب على المسلمين، وهذا المشروع لهم، وبهذا يتيسر للمسلمين تزويج شبابهم وتزويج فتياتهم بالمهور المناسبة والكلف المناسبة من دون مشقة ولا حرج ولا تعاطٍ لما حرم الله.\nوالواجب على ولاة الأمور في كل بلد من الأمراء والحكام أن يعينوا الناس على الخير، وأن يمنعوهم من الشر، وأن يأخذوا على أيدي السفهاء حتى ... الأمور على الوجه الشرعي، هذا هو الواجب على أمير البلد وقاضي البلد وأعيان البلد أن يتعاونوا بينهم في هذا الشيء، حتى يلزموا الناس بالخير ويمنعوهم من الشر، ومتى أصلح الله الرؤساء تبعهم الناس، متى صلح الأمير والأعيان، وتدخلت المحكمة والقضاة حصل الخير الكثير وانتهى الناس عما يضرهم.\nومتى سكت هؤلاء وهؤلاء وهؤلاء زاد الشر، وكثر البلاء، وتعطل الشباب وتعطلت الفتيات وهذا شيء لا يرضاه الله ورسوله، ولا يرضاه أهل الإيمان والعلم، فنسأل الله للجميع الهداية والتوفيق.\nالمقدم: أخونا يسأل يقول: إذا لم يكن هناك سبيل إلى التغيير الذي تفضلتم وبينتم ما يجب أن يكون عليه، هل يلزم المسلم أن يبحث عن زوجة في مكان آخر وفي بلد آخر يتوفر فيه ذلك الجو؟\nالشيخ: نعم، ليس من اللازم أن يتزوج في بلده، لا مانع من أن ينتقل إلى بلد آخر في بلاده بشرط العناية بالمرأة الصالحة البعيدة عما حرم الله، وعن أسباب الفتنة، يتحرى يسأل عنها، فإذا وجدها حرص عليها، يقول النبي ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها ثم قال: فاظفر بذات الدين تربت يداك.\nفالزوج يسعى إلى ذات الدين ويحرص عليها، وإذا حصل مع ذلك جمال أو حسب أو مال فهذا أكثر وإلى خير، لكن لا تكون أكبر همته وأعظم قصده الجمال فربما أطغاها الجمال، وربما أفسدها عليه الجمال، ولكن يحرص على أولًا كونها ذات دين، على كونها ذات دين، ثم يبحث بعد ذلك عما يريد من جمال أو حسب أو غير ذلك، فإذا انضم هذا إلى هذا خير إلى خير، وإلا قدم ذات الدين وإن قل جمالها وإن قل مالها وإن عدم حسبها، فالمرأة بنفسها ودينها لا بحسبها وجمالها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7572/ما-حكم-المنكرات-في-حفلات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18904.mp3","categories":["الشعر والأغاني","قضايا المرأة","الزفاف ووليمة العرس"]},{"id":9941,"question":"هذه رسالة من السائل أحمد علي حسن الزهراني له فيها عدة أسئلة وإن كان قد تكرر أكثرها سؤال حول تارك الصلاة وهل يدفن في مقابر المسلمين، وسؤال حول غلاء المهور وما نتج عنه من تعطل كثير من الشباب والفتيات عن الزواج بسبب غلاء المهور، ويطلب وضع حل لهذه المشكلة، وسؤال آخر عن دعاء الشياطين والبناء على القبور، هذه خلاصة الأسئلة التي وردت في رسالته؟","title":"حكم ترك الصلاة وغلاء المهور ودعاء أهل القبور","answer":"الجواب: أما السؤال الأول وهو تارك الصلاة هل يدفن في مقابر المسلمين؟ فقد تنازع العلماء في حكمه إذا تركها تهاونًا وهو لم يحل وجوبها بل يؤمن بأن الصلاة فريضة، ولكن تركها تهاونا وكسلًا، فذهب قوم إلى أنه لا يكفر بذلك كفرًا أكبر بل كفر أصغر وأنه يدفن مع المسلمين ويغسل ويصلى عليه، وهذا قول معروف عند جمع كبير من أهل العلم.\nوالقول الثاني أنه يكفر كفرًا أكبر وهذا هو الأصح والأرجح.\nفعلى هذا لا يدفن مع المسلمين بل يدفن في محل بعيد عن الناس لا يعرف ويسوى عليه الأرض كسائر الكفرة؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر ولم يستثن أحدًا، ولم يقل: إذا كان جاحدًا لوجوبها، وهذا حديث صحيح رواه أحمد وأهل السنن بإسناد صحيح، وروى مسلم في صحيحه عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والكفر معرف والشرك معرف يرجع للكفر الأكبر والشرك الأكبر، هذا هو الأصح والأرجح لأدلة أخرى كثيرة تدل على أن المتهاون في ترك الصلاة ليس معه من الإسلام شيء بل قد فارق الإسلام نسأل الله العافية والسلامة.\nوأما المهور وما يتعلق بغلائها فهذا قد سبق فيه فتاوى كثيرة ونشرنا عن ذلك نشرات كثيرة، وكتب مجلس هيئة كبار العلماء في ذلك كتابات في الحث على عدم المغالاة والاقتصاد في المهور والولائم وهذا حق، فالواجب على المسلمين أن يتعاونوا في هذا وأن يقتصدوا في المهور والولائم حتى يمكنوا المتوسط في الدخل ومن يعجز عن كثير من المهور ومن مئونة الولائم حتى يمكنوهم من الزواج ويسهلوا لهم الزواج.\nفالمقصود أن هذا شيء يجب على المسلمين التعاون فيه وعلى ولاة الأمور التعاون مع الناس في ذلك حتى يتركوا هذه المغالاة في المهور وفي الولائم، وهذا حق على الجميع واوجب على الجميع أن يتعاونوا فيه وأن يتواصوا به لعل الله جل وعلا يمن بترك الناس لهذا الشيء حتى يحسنوا بذلك إلى فقرائهم وإخوانهم الذين يعجزون عن هذه الأمور.\nوأما ما يتعلق بدعوة الشياطين والاستغاثة بالجن وبأصحاب القبور فهذا من الشرك بالله ، فدعاء الأموات والاستغاثة بالأموات والنذر لهم وطلبهم المدد هذا من الكفر الأكبر، وهذا واقع في كثير من الناس في بلدان كثيرة ودول كثيرة يأتي إلى الميت المشهور الذي يسمونه ولي، فيقول: يا سيدي! اشف مريضي رد غائبي المدد المدد، وهذا كفر أكبر بإجماع أهل السنة والجماعة ولا عبرة بمن خالف من المتأخرين الذي جهلوا هذا الأمر ولم يعرفوه وظنوا أن الشرك توحيد وأن التوحيد شرك فهؤلاء لا عبرة بهم.\nفالأدلة من الكتاب والسنة كلها تدل على أن دعاء الأموات والاستغاثة بالأموات وطلبهم المدد من جنس دعاء الأصنام ومن جنس دعاء الكواكب ومن جنس دعاء الأشجار والأحجار كله شرك بالله، كله من عمل الجاهلية، من جنس عمل أبي جهل وأشباهه من كفار قريش حين دعوا العزى وهي شجرة، وحين دعا أهل الطائفة اللات في عهد النبي ﷺ وهي صخرة كان يلت عليها رجل صالح السويق فعظموها وصاروا يعبدونها من دون الله، هذا كله باب واحد فدعاء الأموات والاستغاثة بالأشجار وبالأحجار وبالأصنام وبالكواكب وبالجن كله باب واحد وكله من الشرك بالله .\nفالواجب على أهل الإسلام أن يحذروا هذه الأمور وأن يحذروها الناس، والواجب على العلماء أن يبذلوا وسعهم في هذا الأمر وأن يجتهدوا في تبيين هذا الأمر للناس في الوسائل وسائل الإعلام المنظورة والمقروءة والمسموعة حتى يكون الناس على بينة، فإن كثيرًا من الناس قد وقع في هذا في بلدان كثيرة ودول متعددة يطوف بالقبر ويدعو صاحبه ويستغيث به وينذر له ويذبح له ويطلبه المدد والغوث ويعرض عن الله عز وجل، وهذا من البلاء العظيم. وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14]  فسمى دعاءهم لغير الله شركًا، وهذا يعم دعاء الأموات من الصالحين والأنبياء ويعم دعاء الجن ودعاء الأصنام وغير ذلك، كله شرك بالله  وكله باطل. بخلاف ما فعله .... المشركون الذين جهلوا الأمر وجهلوا الحق فغيروا وبدلوا، نسأل الله السلامة والعافية، نسأل الله أن يهدي المسلمين وأن يبصرهم بدينهم، وأن يوفق علماءهم وحكامهم لتنبيههم وتعليمهم وإرشادهم ومنعهم من الباطل والشرك إنه خير مسئول سبحانه وتعالى.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8109/حكم-ترك-الصلاة-وغلاء-المهور-ودعاء-اهل-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20002.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":10121,"question":"ما حكم المعونة، وهي الإتيان بشيء خروف أو مال لصاحب العرس؟","title":"حكم مساعدة صاحب العرس","answer":"الجواب: هذا مستحب مساعدته، إذا كان في حاجة مساعدته وإذا كان عرف البلد كذلك، إذا كان في عرف البلد أنه يساعد، أو كان فقير يساعد، كل هذا أمر مطلوب، إن كان عرفًا سوعد، وإن كان فقيراً سوعد، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8292/حكم-مساعدة-صاحب-العرس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27709.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":10396,"question":"تقول في سؤالها الثاني: هل يجوز استخدام وسماع الطبل في الأفراح إذا تعذر وجود الدف؟","title":"حكم الطبل في الأفراح للنساء","answer":"الجواب: لا، لا يجوز استعمال الطبل ولا غيره من آلات الملاهي، كالعود والكمان والموسيقى وأشباه ذلك، إنما يباح الدف فقط، إن وجد وإلا فلا ما لزوم شيء آخر، يكفي التحدث والكلام والأغاني الجائزة بين النساء فيما بينهن لا بأس، وأما الطبل فلا يصلح. نعم.","link":"https://binbaz.org.sa/fatwas/8568/حكم-الطبل-في-الافراح-للنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34003.mp3","categories":["الزفاف ووليمة العرس"]},{"id":10397,"question":"هل يجوز للمرأة المسلمة الرقص بين النساء فقط بمناسبة الأفراح؟","title":"حكم رقص المرأة بين النساء في حفلات الأعراس","answer":"الجواب: لا حرج في الرقص بين النساء خاصة إذا كان ما في أخلاط من الرجال لا بأس بالرقص ولا حرج فيه.. ، ولا نعلم فيه بأسًا، وكذلك الأغاني العادية في مدح الزوج أو الزوجة أو أهل الزوج أو الزوجة، الأغاني التي ليس فيها فحش وليس فيها دعوى إلى منكر ولا تحبيب لمنكر، كل هذا لا بأس به. نعم.\nالمقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8569/حكم-رقص-المراة-بين-النساء-في-حفلات-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34004.mp3","categories":["الزفاف ووليمة العرس"]},{"id":10410,"question":"الأخت أم محمد من جدة بعثت تقول كثيرًا من النساء يرتدين الملابس الغالية الثمن، ويبذلن فيها أموالًا طائلة خاصة في مناسبات الزواج، فما هي نصيحتكم لهن؟ وكذلك يصاحب هذه المناسبات إسراف في المآكل والمشارب؟","title":"الإسراف في المأكل والملبس في مناسبات الزواج","answer":"الجواب: النصيحة التوسط في كل شيء، النصيحة الوسط في الملابس وفي الطعام وفي كل شيء، قال الله جل وعلا -يمدح عباد الرحمن-: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا [الفرقان:67] وقال سبحانه: وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلََّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [الإسراء:29]، فالسنة للمؤمن والمؤمنة التوسط في الملابس وفي الأكل والشرب وفي كل شيء، فلا إسراف وتبذير ولا بخل وتقتير، ولكن بين ذلك في جميع الأمور، في المآكل والمشارب والمفارش والملابس وغير ذلك، الله يهدي الجميع، نسأل الله للجميع الهداية، مصيبة عامة لا حول ولا قوة إلا بالله.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8583/الاسراف-في-الماكل-والملبس-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28013.mp3","categories":["الزفاف ووليمة العرس"]},{"id":10412,"question":"هل يجب على المرأة تلبية دعوة الزواج وخاصة أنه قد يحصل هناك بعض الأخطاء فهل تنصحونهن بنصيحة؟","title":"حكم إجابة الدعوة إن اشتملت على منكر","answer":"الجواب: نعم إن كان هناك منكرات كثيرة فلا يحضرن المنكرات، إما إن كان ما هناك منكر فالحضور مشروع، وإجابة الدعوة مشروعة، لكن إذا كان هناك منكر مثل الخمر، مثل آلات الملاهي فلا يحضر، معذور إلا إذا كان حضوره يترتب عليه إنكار المنكر يحضر وينكر حتى يزيل المنكر، يجمع بين المصلحتين، بين إجابة الدعوة وبين إزالة المنكر، أما إذا كان حضوره لا يؤثر ولا يسمع له، ولا يطاع له، فإنه لا يحضر.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8585/حكم-اجابة-الدعوة-ان-اشتملت-على-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_280/28014.mp3","categories":["الزفاف ووليمة العرس"]},{"id":10973,"question":"السائل يقول: هل حضور حفلات الزفاف التي فيها دف جائزة؟ نرجو منكم التوجيه، وبالنسبة للرقص بالنسبة للنساء هل هو جائز؟","title":"حكم الدف والرقص للنساء في الأعراس","answer":"الجواب:  الدف مستحب في الزواج، في حفل العرس، مستحب الدف للنساء، وكان يفعل في عهد النبي ﷺ ويحضره أزواج النبي -عليه الصلاة والسلام- وهو من إعلان النكاح، فلا بأس بحضوره، ولا بأس بسماع الأغاني المعتادة التي ليست فيها فحش، لا حرج في ذلك، يستحب حضوره، ويستحب فعل الدف أيضًا؛ لأن هذا كله من باب إظهار النكاح، ولا بأس بالرقص أيضًا إذا كان ما فيه إلا النساء، بين النساء لا حرج في ذلك. المقدم: بالنسبة -يا سماحة الشيخ- لمكبرات الصوت التي توضع عادة في حفلات الزواج أيضًا هل لكم توجيه؟ الشيخ: لا حرج في ذلك إذا كانت لإسماع النساء، إذا كان الحفل كبيرًا.. إذا كان الحفل كبيرًا، وكونهم يحتاجون إلى مكبرات الصوت فلا بأس، لكن لا يكون فيه ... يظهر للأسواق وللرجال، يلاحظ هذا أن يكون بقدر الحاجة، يكون بقدر حاجة النساء المستمعات، هذا أحوط. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9151/حكم-الدف-والرقص-للنساء-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28617.mp3","categories":["الزفاف ووليمة العرس"]},{"id":11065,"question":"من السودان السائل (يوسف . أ. أ) يقول: لدينا بعض العادات في الزواج، وذلك بعد عقد القران للرجل والمرأة، بما يسمى: قطع الربط، والربط: هو عبارة عن خيط، أو حزام يربط في منتصف العروس، وذلك يكون يوم ليلة الزفاف، ويطلب من الزوج أن يقطع ذلك الرباط أو الحزام، فهل هذا وارد؟ نرجو توضيح ذلك مأجورين.","title":"عادة قطع الزوج للخيط المربوط على العروس ليلة الزفاف","answer":"الجواب:  هذه عادة بين الناس إذا كانت عادة لهم لا يضر قطعه وإلا ما قطعه ما يضر بالنكاح، لكن قصدهم علامة أنه يعني: دخل عليها... فإذا فعله استجابة لهم وتطييبًا لنفوسهم يكون أحسن.","link":"https://binbaz.org.sa/fatwas/9243/عادة-قطع-الزوج-للخيط-المربوط-على-العروس-ليلة-الزفاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28813.mp3","categories":["الزفاف ووليمة العرس"]},{"id":11514,"question":"سماحة الشيخ: في الزواج أفراح وأفراح كيف تكون الأفراح في الزواج؟","title":"صفة الأفراح الموافقة للشرع","answer":"الجواب:  الزواج يكون فيها الأفراح الشرعية، الدف الشرعي بحضور النساء من غير اختلاط، الدف المعروف ذا الوجه الواحد يكون تضرب به المرأة، وتغني الغناء المعتاد الذي ليس فيه فحش، نعم. العادي لا بأس بهذا، هذا من إعلان النكاح، واجتماع النساء، وهكذا اجتماع الرجال عند الرجل، كله من إعلان النكاح، وهكذا الوليمة من إعلان النكاح، هذا الزواج الشرعي، نعم. المقدم: جزاكم الله خيرًا، حدكم للوليمة سماحة الشيخ؟ الشيخ: نعم؟ المقدم: الحد الذي ترونه للوليمة، مقداره؟ الشيخ: لا يكون فيه إسراف، ويكون فيه اقتصاد، ولو بشاة مثلما قال النبي ﷺ لعبدالرحمن بن عوف قال: أولم ولو بشاة النبي ﷺ قال لعبدالرحمن: أولم ولو بشاة فإذا أولم بشاتين، بأكثر على حسب الجماعة المدعوين، يجعل لهم ما يكفيهم، والنبي ﷺ في بعض الأحيان أولم بوليمة كبيرة ودعا إليها من ....... من لقيت. المقصود: أنه يختلف إذا كانت الوليمة لأناس محدودين، يكون بقدرهم، وإذا كانت دعوة عامة يكون يحتاط، ويجعل الشيء الذي يكفي، وينبغي له عدم التكلف، نعم. يشرع له عدم التكلف، وإذا دعت الحاجة لوليمة كبيرة لكثرة أقاربه، أو كثرة جيرانه؛ فلا بأس، الحمد لله. المقدم: بارك الله فيكم، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9694/صفة-الافراح-الموافقة-للشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38410.mp3","categories":["الزفاف ووليمة العرس"]},{"id":11972,"question":"المستمع محمد سالم رفيع بعث برسالة وضمنها بعض الأسئلة في أحدها يقول: بماذا تنصحون الآباء الذين يكثرون في مهور بناتهم، كأن يطلبوا مبالغ معينة محدودة، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"حكم المغالاة في المهور والإسراف في الولائم","answer":"الجواب:  نصيحتي للجميع التخفيف والتيسير، وعدم طلب الكثير إذا جاء الكفء الطيب، فالمشروع قبوله، وعدم التكلف في المهور، ولا في الولائم، هذا هو الأفضل والأولى والأحوط، لما في ذلك من تكثير الزواج، وإعفاف الرجال والنساء جميعًا، وكثرة الأمة، فالمشروع لأولياء النساء، وللنساء أيضًا أن يتعاونوا في التخفيف، وعدم المطالبة بالمهور الكبيرة، أو بالولائم الكبيرة التي قد تشق على الزوج، وأهل المرأة، وخير الصداق أيسره، فالمشروع التيسير والتسهيل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، هل تقترحون مبلغًا معينًا سماحة الشيخ؟ الجواب: ما جاء في الشرع حد محدود، لكن يختلف هذا بحسب العرف، حسب تغير الأحوال والبلدان والمؤونات، فيستحب التخفيف حسب الطاقة حسب التيسير. المقدم: جزاكم الله خيرًا، إذًا لا تقترحون مبلغًا معينًا؟ الشيخ: لا ما أقترح شيئًا معينًا، إنما التسهيل والتيسير على حسب الأحوال. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10157/حكم-المغالاة-في-المهور-والاسراف-في-الولاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42913.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":12163,"question":"نعود مع مطلع هذه الحلقة إلى رسالة جمعٍ من الأخوات في ليبيا بعثن برسالة ضمنها عددًا من الأسئلة، عرضنا بعضًا منها في حلقات مضت، وفي هذه الحلقة يسألن ويقلن: نرجو الإفادة حول لباس المرأة المسلمة، وما معنى الجلباب؟ إذ أن هناك بعض النساء في مناسبات الأفراح عندما يدخلن المكان الذي تكون فيه المناسبة يقمن بكشف شعرهن، فهل يجوز هذا، مع العلم بأنه لا يوجد رجال في هذه الأماكن؟ وماذا عن الغناء والرقص في الأفراح بين النساء؟","title":"ضابط لباس المرأة وحكم الغناء والرقص للمرأة","answer":"الجواب:  بسم الله، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن استعمال الجلباب أمر مطلوب بين الرجال الأجانب، والجلباب يشبه العباءة، وما أشبهه مما تغطي به المرأة بدنها كله، رأسها وبدنها فوق ثيابها، قال الله تعالى:  يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ.. [الأحزاب:59] الآية، وفي الصحيح عن أم عطية -رضي الله عنها-: أن النبي ﷺ أمر النساء بحضور العيد، بحضور صلاة العيد، قالت: قال بعض النساء: إن إحدانا ليس لها جلباب، فقال -عليه الصلاة والسلام-: لتلبسها أختها من جلبابها.  فالمقصود: أن الجلباب شيء يستر البدن كله، وهو يشبه العباءة من بعض الوجوه. والواجب على النساء التحجب عن الأجانب، وعدم إظهار شيء من الزينة لهم، كأخي الزوج، وأخي زوج الأخت، وغيرهم ممن ليس محرمًا.  ولا بأس بالغناء المعتاد في العرس بين النساء، وضرب الدف الذي هو الطار، والدف له وجه واحد يضرب في مناسبة العرس لإعلان النكاح وإظهاره، وقد جاءت السنة في ذلك، وكان يستعمل في عهد النبي ﷺ، فلا بأس به لإظهار النكاح وإعلانه في وقت مناسب من الليل من دون سهر. ولا بأس -أيضًا- بالرقص ولا حرج في ذلك بين النساء، ولا بأس بالغناء المعتاد الذي ليس فيه دعوة إلى محرم، ولا تزيين للفواحش، ولكنه مدح للزوج، أو الزوجة، أو أهل الزوج، أو أهل الزوجة، ونحو ذلك مما جرت به العادة. كان النساء يغنين في عهد النبي ﷺ في العرس، ويضربن بالدف، ولا حرج في ذلك، بشرط: أن يكون ذلك ليس فيه اختلاط بين الرجال والنساء، بل يكون خاصًا بالنساء في ليلة العرس لإظهار النكاح وإعلانه، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10349/ضابط-لباس-المراة-وحكم-الغناء-والرقص-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44201.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":12567,"question":"ما حكم من لم يولم لزواجه؟ وهل يتأثر عقد النكاح بهذا؟ وهل يعتبر عاصيًا للرسول ﷺ عندما أمر عبدالرحمن بن عوف حين زواجه أن يولم ولو بشاة؟","title":"تأثير وليمة العرس على عقد النكاح","answer":"الجواب:  الوليمة سنة مؤكدة ولو بشاة كما قال ﷺ أولم ولو بشاة لعبدالرحمن بن عوف، ولكن لا يؤثر في النكاح، النكاح صحيح، ولو لم يحصل هناك وليمة، إذا تمت شرائطه وأركانه؛ فهو صحيح، وإن لم يولم، لكن كونه يولم بما تيسر هو السنة، وهو الذي ينبغي، والقول بوجوب الوليمة قول قوي؛ لأن الرسول ﷺ أمر بها أولم ولو بشاة فالقول بالوجوب له قوة، ولو بالشيء اليسير حسب الطاقة، وترك ذلك خلاف السنة، لكنه لا يؤثر في النكاح، ولا يبطله، بل النكاح صحيح إذا استوفى شروطه وأركانه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10768/تاثير-وليمة-العرس-على-عقد-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_411/41103.mp3","categories":["الزفاف ووليمة العرس"]},{"id":12690,"question":"هل إجابة الدعوة واجبة على النساء؛ لأني قرأت أن من لم يجب الدعوة فقد عصى الله ورسوله أو كما قال -عليه الصلاة والسلام- خاصة إذا كان الدعوة لزواج أقارب أو أصدقاء، وسيكون في هذا العرس بعض الأخطاء، وإذا لم نذهب سوف تحصل مشاكل بين الأهل، أفيدونا جزاكم الله خيرًا.","title":"حكم إجابة الدعوة للمرأة","answer":"الجواب:  الأدلة عامة، الأحاديث عامة في وجوب الدعوة، في وجوب الإجابة، بشرط أن لا يكون فيها منكر، فإذا دعيت المرأة إلى وليمة، أو إلى عرس؛ وجب عليها الإجابة، بشرط أن يوافق زوجها وأن يرضى زوجها، وأن تخرج متسترة ومتحجبة بعيدة عن الفتنة، وأن لا يكون في محل الدعوة فتنة بل يكون محل الدعوة آمنًا، ليس فيه فتنة، فإنها تجب الدعوة، أما إذا لم يرض زوجها، ولم يسمح فلا تخرج إلا بإذنه، أو كان في الطريق خطر كذلك لا تخرج أو كان في محل الدعوة خطر -فتنة- اختلاط الرجال بالنساء أو منكرات في محل الدعوة فإنها لا تخرج وهكذا الرجل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10900/حكم-اجابة-الدعوة-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41718.mp3","categories":["الزفاف ووليمة العرس"]},{"id":13050,"question":"هذا سائل رمز لاسمه بـ \"أبو عبدالله\" من الرياض يقول: في وليمة العرس أجمع أهل المتزوج، وأقربائي على خروف، أو خروفين كوليمة، ولا أدعو غيرهم، وأقتصر على ذلك، فهل في ذلك حرج يا سماحة الشيخ؟","title":"المقصود من الوليمة في الأعراس","answer":"الجواب: \n\nليس في ذلك حرج، المقصود: إعلان النكاح، وهذا إعلان -والحمد لله- ما فيه شيء، وإن زدت وقد دعوت زيادة على هذا من أجل المبالغة في الإعلان فهو حسن، لكن لا ينبغي الإسراف، ولا التكلف على حسب طاقتك، نعم. \n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11267/المقصود-من-الوليمة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50510.mp3","categories":["الزفاف ووليمة العرس"]},{"id":13687,"question":"يقول هذا السائل: هل يجوز ذبح أكثر من شاة واحدة في الوليمة؟ وما معنى حرف لو في الحديث: أولم ولو بشاة هذا الحديث متفق عليه، هل هي للتكثير أم للتقليل؟","title":"حكم ذبح أكثر من شاة في الوليمة","answer":"الجواب: الحديث فيه: أولم ولو بشاة قال النبي ﷺ لعبدالرحمن بن عوف، وهي للتقليل، يعني: ولو كان المولم به شاة، هذا يدل على أن الأفضل الأكثر شاتين ثلاث أربع؛ حتى يكون الجمع أكثر الذين يستفيدون من هذا الزواج، ومن وليمة الزواج، وحتى يكون إعلانه أظهر، يكون إعلانه أكثر وأظهر، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12039/حكم-ذبح-اكثر-من-شاة-في-الوليمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51916.mp3","categories":["الزفاف ووليمة العرس"]},{"id":14684,"question":"تقول السائلة في آخر أسئلتها: هل يجوز ضرب الدف قبل يوم الزواج أو بعده؟ علماً بأنني سمعت بأنه لا يضرب إلا في يوم الزفاف فقط.","title":"حكم ضرب الدف للنساء قبل الزواج وبعده","answer":"الجواب: السنة أن يضرب في الزفاف ليلة الزفاف، هذا هو السنة، وهكذا للجواري أيام العيد لا بأس، أما غيره فتركه أحوط، تركه الأحوط للنساء، إنما السنة ضربه بإعلان النكاح ليلة الزفاف، أو كان في يوم العيد، كما فعله بعض الجواري عند النبي ﷺ، وقال لما أنكر عليهن أبو بكر قال: دعهن فإن لكل قوم عيدًا، وهذا عيدنا أهل الإسلام فدل على أنه يسمح للجواري والنساء بضرب الدف يوم العيد، عيد الفطر عيد النحر، وهكذا في الزواج لإعلان النكاح، أما الطبل لا، لا يستمع للطبل، ولكن الدف ذو الوجه الواحد، نعم.","link":"https://binbaz.org.sa/fatwas/13172/حكم-ضرب-الدف-للنساء-قبل-الزواج-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56011.mp3","categories":["النظر والخلوة والاختلاط","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":14808,"question":"أيضًا يقول: من بين التقاليد والعادات الدارجة عندنا أن تقوم العروس في حفل عرسها بالرقص وسط المدعوين، بفستان الزفاف، الذي عادةً ما يكون غير ساترٍ لجسمها. نرجو التوجيه في هذا. جزاكم الله خير الجزاء.","title":"حكم رقص العروس في حفل عرسها","answer":"الجواب: إذا كان ذلك بين النساء فقط، ليس فيه رجال؛ فلا حرج أن ترقص بينهم مع التستر، حيث لا يبدو منها إلا ما جرت العادة بظهوره، كالرأس واليدين والقدمين، ونحو ذلك، تكون متسترة في بقية جسمها، ولكن لا مانع من رقصها عندهم بإظهار رأسها، ونحو ذلك؛ لا بأس بذلك، عند النساء خاصة، وعورة المرأة بين النساء ما بين السرة والركبة، لكن كونها تستر صدرها وساقيها، يكون أفضل وأولى، ولكن ترقص برأسها بين النساء، لا حرج في ذلك. أما إذا كان هناك رجال؛ فلا يجوز، هذا منكر، وحرام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13302/حكم-رقص-العروس-في-حفل-عرسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64203.mp3","categories":["قضايا المرأة","الزفاف ووليمة العرس"]},{"id":15624,"question":"السائل إبراهيم أبو حامد يقول: نسمع أن بعض الناس تم -أو يعقد- قرانه -أي: الزواج- بالمسجد الحرام، ويقولون بأنه مكان مبارك، نرجو أن يكون الزواج كذلك، وموفق -إن شاء الله-، فما الحكم الشرع في ذلك يا شيخ؟","title":"حكم عقد الزواج في المسجد الحرام للتبرك","answer":"الجواب: لا أعلم في هذا دليلًا، في أي مكان عقد فلا بأس في المسجد أو في البيت أو في أي مكان لا بأس، لا أعلم لخصوصية المسجد دليلًا واضحًا.  أقول: أو لا أذكر دليلًا واضحًا في عقده في المسجد، نعم، عقد النكاح يعني، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14160/حكم-عقد-الزواج-في-المسجد-الحرام-للتبرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57107.mp3","categories":["الزفاف ووليمة العرس"]},{"id":15794,"question":"إذا غنت المرأة بأغان معينة دون موسيقى فهل يعتبر هذا محرم؟","title":"حكم غناء المرأة بغير موسيقى","answer":"الجواب: الأغاني يجب تركها إذا كانت قد تتعلق بذم ما هو ممدوح، أو مدح ما هو مذموم، أو دعوة إلى الفاحشة، أما إذا كانت الأغاني شيء قليل عارض بيت بيتين، ثم تترك، ولا يترتب عليها شر على أحد، وليس معها موسيقى ولا شيء من آلات الملاهي الأمر سهل، البيت والبيتين. أما إذا كان على سبيل الشعر العربي الأشعار العربية السليمة، فهذا لا بأس بالشعر، يقول النبي ﷺ: إن من الشعر حكمة فإذا كانت أشعارًا عربية باللغة العربية في مدح الحق، وذم الباطل، في الدعوة إلى الخير، فهذا لا بأس به. أما الأغاني التي تهيج الناس إلى الفساد والشر، أو الزنا أو غيرها من المنكرات، فهذه لا تجوز، لكن بيت أو بيتين تقوله المرأة أو يقوله الرجل ليس لقصد الشر، وإنما مر على لسانه عارض، فهذا أمره سهل، وقد بيَّن جمهور أهل العلم أن لهو الحديث هو الغناء، يقول ابن مسعود : \"الغناء ينبت النفاق في القلب كما ينبت الماء البقل\" يريد قوله تعالى: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ[لقمان:6] فلهو الحديث هو الغناء، فالواجب تركه، والحذر منه، وإذا كان معه آلات لهو موسيقى أو كمان أو عود أو ما يشبه ذلك فهذا التحريم أشد، بل قال بعض أهل العلم: إنه إجماع، حكاه ابن الصلاح، إجماع أهل العلم في التحريم. فالواجب الحذر من ذلك، وعدم التساهل في هذه الأمور إلا إذا كان مثلما تقدم على طريقة الشعر العربي الألفاظ العربية لا بألفاظ الغناء، شعرًا عربيًا فيما ينفع المسلمين في مدح الحق، في ذم الباطل، في الدعوة إلى الخير، والتشجيع عليه، كأشعار المعروفين بالخير، مثل حسان بن ثابت، وكعب بن مالك، وعبدالله بن رواحة، والشعراء بعدهم بالحق، الشعراء الذين يتحرون الحق شعرهم طيب ومقبول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14379/حكم-غناء-المراة-بغير-موسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74216.mp3","categories":["الشعر والأغاني","قضايا المرأة","الزفاف ووليمة العرس"]},{"id":16305,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع سالم سعيد عبد الولي يمني مقيم في المملكة، يسأل لو تكرمتم ويقول: يوجد في قريتنا مسجد يصلي فيه الناس، وكذلك يجتمع فيه الناس من القرى المجاورة لأداء صلاة الجمعة، ولكن هناك عادة اعتاد الناس عليها وهي: إذا نوى أحدهم إقامة زواج؛ أخبر الناس بذلك في المسجد بعد صلاة الجمعة، فهل هذا جائز؟","title":"حكم الدعوة إلى وليمة العرس في المسجد","answer":"الجواب: لا نعلم بأسًا في ذلك، هذا ليس من إنشاد الضالة، هذه دعوة إلى الوليمة، قد وقع مثل هذا في عهد النبي ﷺ فأرسل له بعض الصحابة يدعوه، فقال للحاضرين: توجهوا إلى فلان يدعوكم إلى وليمة، ولم ينكر ذلك على من دعاه، أرسل أبو طلحة أنسًا في بعض الأيام يدعو النبي ﷺ إلى وليمة، فقال للحاضرين: قوموا إلى دعوة أبي طلحة. فالمقصود: أن هذا لا بأس به، إذا قال شخص من الحاضرين: تفضلوا للعشاء، أو للغداء؛ لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15000/حكم-الدعوة-الى-وليمة-العرس-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81003.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":16312,"question":"بعد هذا رسالة وصلت إلى البرنامج من المستمع سالم سعيد عبد الولي يمني مقيم في المملكة، يسأل لو تكرمتم ويقول: يوجد في قريتنا مسجد يصلي فيه الناس، وكذلك يجتمع فيه الناس من القرى المجاورة لأداء صلاة الجمعة، ولكن هناك عادة اعتاد الناس عليها وهي: إذا نوى أحدهم إقامة زواج؛ أخبر الناس بذلك في المسجد بعد صلاة الجمعة، فهل هذا جائز؟","title":"حكم الدعوة إلى وليمة العرس في المسجد","answer":"الجواب: لا نعلم بأسًا في ذلك، هذا ليس من إنشاد الضالة، هذه دعوة إلى الوليمة، قد وقع مثل هذا في عهد النبي ﷺ فأرسل له بعض الصحابة يدعوه، فقال للحاضرين: توجهوا إلى فلان يدعوكم إلى وليمة، ولم ينكر ذلك على من دعاه، أرسل أبو طلحة أنسًا في بعض الأيام يدعو النبي ﷺ إلى وليمة، فقال للحاضرين: قوموا إلى دعوة أبي طلحة. فالمقصود: أن هذا لا بأس به، إذا قال شخص من الحاضرين: تفضلوا للعشاء، أو للغداء؛ لا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15000/حكم-الدعوة-الى-وليمة-العرس-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81003.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":16682,"question":"ما هي الطريقة المناسبة لإقامة مراسم الزواج، والمآتم، مأجورين؟","title":"الطريقة المناسبة لإقامة مراسم الزواج والمآتم","answer":"الجواب: الزواج يجب إعلانه عند أهل الزوج، أو أهل الزوجة، يجب إعلانه حتى يعلمه الجيران والناس، أمر النبي ﷺ بإعلان النكاح حتى يعرف أنه نكاح، ما هو بزنا، وأما المأتم لا، المآتم يجب تركها، الواجب ترك المآتم، والبدع، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15410/الطريقة-المناسبة-لاقامة-مراسم-الزواج-والماتم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58406.mp3","categories":["الزفاف ووليمة العرس"]},{"id":16768,"question":"سماحة الشيخ لعل المستمع ينتظر كلمة من سماحتكم حول تيسير أمر الزواج؟","title":"توجيه حول تيسير أمور الزواج","answer":"الجواب: الزواج قد تم، إنما عليه الآن الوفاء بما التزم، لكن نوصي غيره بالتسهيل في المهور، وعدم التكلف، ينبغي للمؤمن ألا يتكلف، أو المرأة، وأخوها، وكذلك هي وأمها؛ ينبغي لهم التسامح في الأمور وعدم التشديد، وأن تكون المهور على حسب حال الزوج، لا يكلف ما لا يطيق، بل ينبغي التخفيف، والتيسير في المهور، وفي الولائم أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15517/توجيه-حول-تيسير-امور-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82203.mp3","categories":["الصداق","الزفاف ووليمة العرس"]},{"id":17125,"question":"أخيرًا تسأل سماحتكم عن حكم الطبل في الأعراس؟","title":"حكم الطبل في الأعراس","answer":"الجواب: لا يجوز الطبل في الأعراس، ولا في غير الأعراس، إنما السنة الدف ذو الوجه الواحد للنساء في العرس؛ لأنه من باب إعلان النكاح، فالرسول ﷺ سمح للنساء من باب إعلان النكاح الدف، والغناء العادي بين النساء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15940/حكم-الطبل-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72206.mp3","categories":["قضايا المرأة","الزفاف ووليمة العرس"]},{"id":17445,"question":"هذا السائل الذي أرسل بهذا السؤال ( أ. م. أ) يقول: هل يجوز للإمام في يوم الجمعة أن يدعو لوليمة زواج على المنبر قبل أسبوع من تاريخ الزواج؟","title":"حكم الدعوة للوليمة في خطبة الجمعة","answer":"الجواب: الأظهر لي والأقرب عندي أنه لا يفعل بذلك، ليست المنابر محلًا للدعوة للولائم، المنابر محل للدعوة لطاعة الله، واتباع شريعته، وتعظيم أمره ونهيه، أما دعوة الولائم تكون في وقت آخر، الذي يظهر لي أنه لا ينبغي للأئمة، والخطباء أن يدعوا للولائم في خطبة الجمعة، ولا في خطبة العيد، دعوة الولائم تكون بالمكاتبة، أو بالتلفون، أو بإرسال رسول له.. وما أشبه ذلك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16317/حكم-الدعوة-للوليمة-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77205.mp3","categories":["الزفاف ووليمة العرس"]},{"id":17449,"question":"هذا السائل الذي أرسل بهذا السؤال ( أ. م. أ) يقول: هل يجوز للإمام في يوم الجمعة أن يدعو لوليمة زواج على المنبر قبل أسبوع من تاريخ الزواج؟","title":"حكم الدعوة للوليمة في خطبة الجمعة","answer":"الجواب: الأظهر لي والأقرب عندي أنه لا يفعل بذلك، ليست المنابر محلًا للدعوة للولائم، المنابر محل للدعوة لطاعة الله، واتباع شريعته، وتعظيم أمره ونهيه، أما دعوة الولائم تكون في وقت آخر، الذي يظهر لي أنه لا ينبغي للأئمة، والخطباء أن يدعوا للولائم في خطبة الجمعة، ولا في خطبة العيد، دعوة الولائم تكون بالمكاتبة، أو بالتلفون، أو بإرسال رسول له.. وما أشبه ذلك، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16317/حكم-الدعوة-للوليمة-في-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77205.mp3","categories":["الزفاف ووليمة العرس"]},{"id":18861,"question":"عندما يتزوج رجل امرأة، يقال: إنه يجب أن يصلي ركعتين له، وركعتين لشريكة حياته، سؤالي: ماذا يقول عندما ينوي في الصلاة؟أرجو أن تجيبوني، جزاكم الله خيرًا.","title":"حكم صلاة ركعتين ليلة الدخول على الزوجة","answer":"الجواب: يروى عن بعض الصحابة صلاة ركعتين عند الدخول على زوجته أول ليلة، ولا أعلم في هذا نصًا عن النبي -عليه الصلاة والسلام-، فإن فعله فلا بأس، إذا صلى ركعتين، ودعا ربه أن الله يوفقه، ويجمع بينه وبينها على خير، فهذا حسن -إن شاء الله- ولا حرج فيه، وإن صلت هي كذلك ركعتين ودعت الله أن الله يجمع بينهما على خير وهدى، كل هذا طيب، ولكن لا أعلم في هذا حديثًا صحيحًا عن رسول الله -عليه الصلاة والسلام- والأمر في هذا واسع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17995/حكم-صلاة-ركعتين-ليلة-الدخول-على-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92206.mp3","categories":["الزفاف ووليمة العرس"]}]
